quests[27045] = { id = 27045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waiting to Exsanguinate", description = "The Gilneas Liberation Front leader, Darius Crowley, has been meeting with another worgen inside this cottage for the past three days. I'm not sure what's going on, but we need to get inside the cottage and find a good hiding place from where we can eavesdrop.\n\nIt's now or never, {race}. We may never get another shot.\n\nJust promise me that if I don't make it, you'll return to Forsaken High Command and inform Belmont of whatever we discover.", sourceObjective = "Enter the Ivar Cottage and find a suitable hiding place upstairs. Then eavesdrop on Lord Darius Crowley.", completion = "Alas, poor Yorick! I knew her, {name}. An assassin of infinite courage...\n\nNow, tell me what's going on? What did you and Yorick discover?", sourceObjectiveStatus = "unverified-source-field" }
quests[27046] = { id = 27046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear of Boring", description = "The gyreworms infest the rock, eating away at it until our home will one day collapse. For every one that is killed, twice as many burst forth to follow, but we must carry on the fight. They must be extinguished.\n\nGo to the Crumbling Depths and slaughter any worms that you can find.", sourceObjective = "Kill 10 gyreworms.", completion = "You wage a war that we cannot. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27047] = { id = 27047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motes", description = "Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much.\n\nAs a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?", sourceObjective = "Recover 10 Motes of Painite.", progress = "Painite is one of the most valuable materials to us, particularly due to our inability to reach most of the deposits on our own.", completion = "Well done, {race}. These will do well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27048] = { id = 27048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground Economy", description = "Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits.\n\nUse these bombs to blow out chunks from the bigger formations.\n\nI've got a nasty habit of packin' the explosives a bit thick. Mind the kick.", sourceObjective = "Use Ricket's Tickers to gather 3 Deep Alabaster Crystals, 3 Deep Celestite Crystals, 3 Deep Amethyst Crystals, and 3 Deep Garget Crystals.", progress = "Boom?", completion = "Well played!\n\nI've got this pretty sweet deal going. A bunch of shmucks go up there to Therazane's Throne and give all kinds of gold to D'lom for who-knows-what kinda crap. He forks all that cash over to me for these crystals. I go home freakin' rich for a couple chunks of rock.\n\nDon't tell no one though. I don't want no competition springin' up.\n\nThink you can come back later to help me get another load of crystals out?", sourceObjectiveStatus = "unverified-source-field" }
quests[27049] = { id = 27049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Rock", description = "The corruption of the Crimson Expanse has not subsided. Destroy the Fungal Behemoths that shower their filth upon our realm. If they continue to rise, we will continue to destroy them.", sourceObjective = "Kill 8 Fungal Behemoths.", completion = "Once the growth starts, it is near impossible to stomp back into submission. Through persistence our realm will one day be cleansed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27050] = { id = 27050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Fury", description = "Something upon the Crimson Expanse continues to spur disgusting growths upon the rock. New fungi are rising, and they need to be crushed before they can spread.", sourceObjective = "Destroy 10 of the newly sprouted mushrooms in the Crimson Expanse.", completion = "You are proficient at stepping on things. You would make an excellent giant.", sourceObjectiveStatus = "unverified-source-field" }
quests[27051] = { id = 27051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Persistence", description = "The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse.\n\nHunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.", sourceObjective = "Retrieve a Bag of Verlok Miracle-Grow from the Verloks upon the Crimson Expanse.", progress = "Have you done as I've asked of you? We must weed out whatever growth agent remains within their possession.", completion = "Thank you, {race}. We will weed the rest out of their possession in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27053] = { id = 27053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahrron's Withering Cauldron", description = "My analysis is complete!  The blight that affects the animals here is no residual disease.  No, it is something new... and I think I know what it is.\n\nThe Cult of the Damned maintains a plague cauldron on a farm called Gahrron's Withering.\n\nThis farm is due southeast of us, close to where the Eastern Plaguelands begin.  I need a sample from this cauldron to verify my suspicions.\n\nEliminate the cauldron lord present there for its key.  You will then be able to access the cauldron and obtain my sample.", sourceObjective = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.", progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "Cauldron Lord Soulwrath's key disintegrates as it touches the lock on the access panel at the base of the cauldron's platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron's framework.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Field Agent Kaartish back at the Menders' Stead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27054] = { id = 27054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Acts", description = "The Cult of the Damned maintains a small camp to the east, Malicia Outpost, which they use for field training outside of the Scholomance.  We may have allowed them to proceed unchecked with this training for too long.\n\nIf cultists are truly using this plague to inoculate the wildlife, then Malicia Outpost must be where the inoculation is occurring.\n\nInstructor Malicia runs the outpost.  Find her, slay her, and find out who she's taking orders from.", sourceObjective = "Kill Instructor Malicia and obtain her Cult Orders.", progress = "You take a look at the paperwork Malicia was carrying...", completion = "The orders in Malicia's possession incriminate Darkmaster Gandling of the Scholomance, but they also conceal another important bit of information.", sourceObjectiveStatus = "unverified-source-field" }
quests[27055] = { id = 27055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students of Krastinov", description = "The Cult orders state that the plague from the cauldron at Gahrron's Withering is in fact being used for TWO purposes.  The first is the practice of spreading disease through the animals of the plaguelands, which you already knew about.\n\nThe remainder of the plague is being shipped to the Weeping Cave, a cavern north of Malicia's Outpost, for use in some dark experiments.  Students of the Scholomance are using this plague to re-animate the dead!\n\nCertainly they must be stopped.", sourceObjective = "Kill 2 Krastinovian Disciples, 2 Flesh-Cobbled Brutes, 2 Flesh-Cobbled Rippers, and 4 Unholy Corpuscles within the Weeping Cave in Western Plaguelands.", completion = "You have gone above and beyond, {name}.  Not only have we set back the Cult of the Damned in their crusade to re-plague the plaguelands, but you have uncovered another set of dire plans: they continue to re-animate the dead!\n\nYour name will definitely be mentioned when this information is presented to Highlord Fordring, {name}.  You have my thanks, and the blessing of the Argent Crusade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27056] = { id = 27056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belmont's Report", description = "<Belmont hands you a sealed envelope.>\n\nDeliver this report to Lady Sylvanas Windrunner. It is my assessment of the situation in Silverpine based upon your and Yorick's field work.\n\nIf we do not stamp out the worgen insurgents, they will overrun us. The time to act is now!", sourceObjective = "Deliver Belmont's Report to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", progress = "Kneel before your queen, {name}.", completion = "Crowley... A gnat. An insect, waiting to be crushed beneath my boot heel.\n\nSo he thinks to rouse the feral worgen of Silverpine? We shall show him and his allies the might of the Forsaken!\n\nBut first we must clean up the mess made by the Warchief's fleet. Without their aid we may lose this war.", sourceObjectiveStatus = "unverified-source-field" }
quests[27057] = { id = 27057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Stead", description = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to Field Agent Kaartish at the Menders' Stead.", sourceObjective = "Bring the Filled Gahrron's Withering Bottle to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", progress = "Gahrron's Withering houses a viciously potent plague cauldron.  Once we have a sample of the plague it spews forth, we will be able to determine whether the Cult of the Damned is truly responsible for continuing to poison the land.", completion = "Good work.  One moment please...\n\n<The draenei takes a moment to compare your sample with a sample he presumably had distilled earlier.>\n\nYes, this appears to be the same corruption that is affecting the wildlife.  With this knowledge, and with your combat expertise, we may have the power to stop this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27058] = { id = 27058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", sourceObjective = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", completion = "You did it! You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Mowi gets up on her tippy toes and gives you a kiss on the cheek.>\n\nNow I'm certain that I have something around here for you.\n\n<She begins rummaging around for your reward.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27059] = { id = 27059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", sourceObjective = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", completion = "You did it! Excellent work, my boy. You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Examiner Rowe pats you on the back with his bony hand.>\n\nNow I'm certain that I have something around here for you.\n\n<He begins rummaging around for your reward.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27060] = { id = 27060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Cow", description = "<Farmer Wollerton tries to pull himself together.>\n\nCows? You're asking about the missing livestock?\n\nI normally just let the cows graze north of the house here. Occasionally one gets spirited away. Leaves a trail of gore. Who would do such a thing?\n\nI'm afraid to follow that trail myself... something sick is happening in Stormwind!", sourceObjective = "While escorting Anduin Wrynn, follow the trail of gore from Farmer Wollerton's Stead to the crime scene. Keep Anduin alive. If he's not with you, he will be waiting in Stormwind Keep.", progress = "This doesn't sound like ordinary cattle rustlers. Something strange is happening here, right in the middle of my city.", completion = "That was a close one! I can't believe you stood your ground against so many at once.\n\nIt looks like this site was used for some kind of twisted Twilight's Hammer initiation ritual. They're definitely active in Stormwind. What's this?\n\n<Anduin finds a badge resting on the shrine.>\n\nThis badge shows a crossed axe and hammer. It looks old. If we keep poking around, we might figure out what it means...", sourceObjectiveStatus = "unverified-source-field" }
quests[27061] = { id = 27061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Overlook", description = "The dragon they're speaking of is Abyssion, {name}.  It's not going to be easy to get the fragment off of him.\n\nMeet with Mylra again.  She is operating nearby at the Twilight Overlook.\n\nShe will tell you what our next move will be.", sourceObjective = "Speak to Stormcaller Mylra at the Twilight Overlook in Deepholm.", completion = "So we're going to have to take on Abyssion to get the fragment?  This operation just got a whole lot more difficult all of a sudden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27062] = { id = 27062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Threat", description = "The Quilboar in Razorfen Downs seem to have allied with the Scourge. This is dark news for us, {class}. We have dire enough problems dealing with these Grimtotem, we won't be able to handle an attack by the Scourge. Venture into Razorfen Downs, east of here, and see if you can find anyone that may be able to help you stop them before they decide to attack here.", sourceObjective = "Find help in Razorfen Downs.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27063] = { id = 27063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Threat", description = "The Scourge are a direct affront to nature. They have managed to corrupt the Quilboar in Razorfen Downs and now threaten to spread further into Thousand Needles and eventually, I fear, west into Feralas. You must go there and do anything you can to confine them. Perhaps you can find someone in the area to help you? The winds whisper of a powerful presence in the area.", sourceObjective = "Find help in Razorfen Downs.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27064] = { id = 27064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Holding Out on Us", description = "{name}, it almost seems like Samuelson is trying to intentionally waste your time. The dockworkers don't know anything. More importantly, explosives are missing from Stormwind Harbor!\n\nYou know what I think? I bet Samuelson knows more than he's letting on. He probably has a lead on Twilight's Hammer and wants all the credit and glory for himself.\n\nWe should peek through his records at the SI:7 headquarters. Take me there and I should be allowed to look at his files and find out what he really knows.", sourceObjective = "Escort Anduin Wrynn to the third floor of SI:7 Headquarters in the Old Town district of Stormwind. If he is no longer with you, you can find Anduin in Stormwind Keep.", progress = "It's time we got some answers!", completion = "This is REALLY suspicious, {name}! Samuelson doesn't have a shred of info here about the Twilight Hammer - it's almost like he's not investigating them. Yet he's got a complete catalog of the missing explosives.\n\n\n\nAnd I found this funny badge with a symbol on it: A crossed axe and hammer.\n\nIt all means something, but what?", sourceObjectiveStatus = "unverified-source-field" }
quests[27065] = { id = 27065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief's Fleet", description = "Our reinforcements from Kalimdor arrived last night. Three orc gunships full of supplies, weapons and soldiers. Three orc gunships lost to Bloodfang's damned worgen.\n\nHow could an entire orc fleet lose to a small band of enemy combatants that lack any siege weaponry? An important question that you will answer for me.\n\nGather your gear and report to the orc admiral, Hatchet, at the Forsaken Rear Guard, southwest of here.\n\nGet those orcs operational, {name}.\n\nI await your full report.", sourceObjective = "Report to Admiral Hatchet at the Forsaken Rear Guard in Silverpine Forest.", completion = "This fiasco may go down as one of the biggest embarrassments in the history of naval warfare. How did this happen? Drunk happened. That's how.", sourceObjectiveStatus = "unverified-source-field" }
quests[27066] = { id = 27066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing in a Flash", description = "I want to teach you a versatile and quick healing technique, {name}. This heal is one you will find yourself using often.\n\nThere is no lack of braves injured in our battles against the Bristlebacks, so you'll have a chance to put your new knowledge to use right away. Practice your new healing technique on the wounded braves around Camp Narache.", sourceObjective = "Learn Flash Heal from Seer Ravenfeather. Practice using Flash Heal 5 times on Wounded Braves in Camp Narache.", completion = "Thank you for your help in seeing to the wounded braves. I'm sure that you will often find your healing skills in demand. Return to me when you need further instruction.", sourceObjectiveStatus = "unverified-source-field" }
quests[27067] = { id = 27067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejuvenating Touch", description = "I want to teach you a basic healing technique, {name}. This spell will allow you to aid wounded allies by healing their wounds over a short period of time.\n\nMany braves have been injured in our fight to defend Camp Narache, so your healing skills will be put to good use. Practice your new healing technique on the wounded braves around Camp Narache.", sourceObjective = "Learn Rejuvination from Gart Mistrunner. Practice using Rejuvination on a Wounded Brave in Camp Narache.", progress = "Have you seen to the injured of the wounded?", completion = "You have a knack for the healing arts, {name}. Wherever you go, your skills as a healer will be in demand. Return to me when you are ready for more training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27068] = { id = 27068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Ukorz Sandscalp", description = "Take a good look, mon. Dis is how it goes, betrayal after betrayal. I backstab you for the sword, and den Chief Ukorz go and backstab me even better for it.\n\nThat's life, yah! Or was...\n\nNow, I know you don't got no love for Mazoga. But I know you goin' in der anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of de Sandfury deserves...a gory death.\n\nMaybe I leave some of my belongin's without a curse before passin' on if you do, yah?", sourceObjective = "Kill Chief Ukorz Sandscalp.", completion = "He's gone? Did he have the sword?\n\nNah...don't tell me. Don't matter no more. Mazoga don't care.\n\nI'm off now, mon. De consequences of my actions await me. Take whatever I was holdin'... I don't need it where I'm goin'...", sourceObjectiveStatus = "unverified-source-field" }
quests[27069] = { id = 27069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel Thunder", description = "We may not have to live down the shame of this defeat, {name}. The Warchief will likely have us all executed instead.\n\nI'll be damned if we don't go down without a fight. Although the whole beachhead is overrun by Bloodfang worgen, there may still be hope. I want you to accompany one of our sea pups to the beachhead, directly west of here, and recover our supplies. Return to me when the pup can carry no more.", sourceObjective = "Recover 5 Sea Dog Crates.\n\nSpeak with Admiral Hatchet to get another Orc Sea Pup if you unexpectedly lose yours.", completion = "Within these crates are held STEEL THUNDER! With our weaponry returned we might have a chance to redeem ourselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[27070] = { id = 27070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fool's Errand", description = "I heard that a troll in here, Hydromancer Velratha I think she was called, has come into the possession of a very rare, beautiful, and powerful piece of jewelry called the Tiara of the Deep. She uses it to control the powerful demigod Gahz'rilla, whose very scales are said to crackle with energy. Do you know what all of that means, {race}?\n\nI need it! Kill Velratha, take the Tiara of the Deep, and kill Gahz'rilla for one of his scales. Bring them all back to me pronto! I'll reward you handsomely.", sourceObjective = "Obtain the Tiara of the Deep and Gahzrilla's Electrified Scale.", progress = "Do you have what I need?", completion = "Excellent! This Tiara will grant me complete control of the water around here, and the Electrified Scale will serve to power all the machines I need to use it all to my advantage!\n\nYou're going to make me a very rich and powerful goblin! You can have this, it's nothing compared to what I'll have soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27071] = { id = 27071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Sandfury", description = "De Sandfury are a resilient tribe. Dey have survived sandstorms an' years an' years of other tings long covered by da sands. It would be foolish to assume that the only forces here are da trolls. We been tamin' da scarabs, breedin' da sul'lithuz, an' raisin' our dead to keep on fightin' for all eternity as zombies.\n\nRuuzlu, da right hand of Chief Ukorz Sandscalp, be plannin' to use dem to retake Tanaris for de Sandfury empire. You best be killin' da trolls in charge of dis if you want to live, mon.", sourceObjective = "Kill Theka the Martyr, Witch Doctor Zum'rah, Antu'sul, and Ruuzlu.", completion = "You killed dem? All of dem? And you return alive?\n\nTake what you want off my body, den. It's mostly curse-free, Mazoga promises.", sourceObjectiveStatus = "unverified-source-field" }
quests[27072] = { id = 27072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Barracks", description = "I recognize the symbol on these badges from before Deathwing's attack on the city. It belonged to soldiers in the old barracks, west of town overlooking the harbor.\n\nYour timing couldn't be better. One of my top agents, Jack Bauden, has been trying to infiltrate the Twilight's Hammer cult for me. Last night he went missing. If you and Anduin are right, the cultists are holed up in the old barracks. Time is urgent! Assault the old barracks, take out those cultists, and rescue Jack Bauden.", sourceObjective = "Go to the Old Barracks and slay 6 Crazed Cultists, then locate Jack Bauden.", progress = "<Bauden is unconscious. This area still swarms with cultists! You'd better clear them out before investigating.>", completion = "<You slap Bauden around until he wakes up.>\n\n{class}? What are you doing here?\n\nI'm SI:7 Agent Jack Bauden. This is the longest day of my life.", sourceObjectiveStatus = "unverified-source-field" }
quests[27073] = { id = 27073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give 'em Hell!", description = "It's the goblins' fault, {race}!\n\n<hic!>\n\nYou see, we set off for Silverpine from Bilgewater Harbor, over in Azshara. Huge mistake that was! Never has such a den of inequity and sin existed in our great empire. Those damnable goblins fueled our every vice and set us off to sail with barrels full of ale. \n\n<hic!>\n\nThe shame of it all leaves a mark greater than any scar. Honor must be restored! Kill the Bloodfang worgen that ambushed us. They're scavenging the wreckage to the southwest.", sourceObjective = "Kill 10 Bloodfang Scavengers.", progress = "Give 'em hell, {race}!", completion = "Looks as if you really gave those worgen a beating and, in the process, lifted the \"shame haze\" they cast over us. Perhaps the sea dogs will quit drinkin' now.\n\nWho am I kidding?\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[27074] = { id = 27074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Hammer", description = "You've done what I thought was impossible! I'm done moping around here. It's time to gnome up.\n\nI've got to find my father. But you! Don't bother yourself with me any longer. You've got to keep fighting these cultists.\n\nGo talk to Ashlan Stonesmirk to the east. He's trying to stop the Twilight's Hammer, but he has nobody to help him. You're his only hope!\n\nDon't give up, {name}. I won't.", sourceObjective = "Talk to Ashlan Stonesmirk near Mo'grosh Stronghold in Loch Modan.", completion = "You hit the twilight camp at the center of the lake? Not bad, lad!\n\nIf you're ready to take the fight right to their doorstep, I've got your chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27075] = { id = 27075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Cho'gall", description = "The Twilight's Hammer started as a clan of the savage Horde. Their leader, Cho'gall, slowly turned his band of ogres into a death cult, welcoming anyone insane enough to wish for the end of all existence. As you can see, there's still plenty of ogres among their ranks; deranged, fanatical, and just as strong as before.\n\nThese crude monsters have the gall to come here and spread their filth across our land. The more you kill, the better off Loch Modan will be, {name}.", sourceObjective = "Kill 7 Mo'grosh ogres in the Mo'grosh Stronghold.", completion = "It may look grim, but we'll win with your help, {name}. They won't keep the dwarves down.", sourceObjectiveStatus = "unverified-source-field" }
quests[27076] = { id = 27076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking and Entering", description = "A good buddy of mine, Weegli Blastfuse, joined up with Sergeant Bly and his group of outcasts to invade Zul'farrak and claim the legendary Sul'thraze as their prize. Of course, they underestimated the Sandfury tribe and now they're all trapped awaiting execution to please their demigod, Gahz'rilla!\n\nIf you free him, he'll help you blast your way to Ukorz's private chamber where he keeps at least part of the blade.\n\nKill his captors, Nekrum Gutchewer and Shadowpriest Sezz'ziz as revenge...I'll repay ya.", sourceObjective = "Free Weegli Blastfuse and kill Nekrum Gutchewer and Shadowpriest Sezz'ziz.", completion = "Wow! I knew I could count on you! Here's something for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27077] = { id = 27077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clutching at Chaos", description = "The cultists of the Twilight's Hammer use their powers to draw elementium metal from deep beneath the earth. They coax it out into twisted spikes to form their buildings, rooted right into the defiled ground.\n\nThe ogres here seem to be in the middle of weaving the stuff, and we need to strike while they're still twisting it into shape.\n\nTear the spikes right out of the ground while they're still pliable, and bring them back to me! We're not going to give these curs a single inch of our land.", sourceObjective = "Pull up 10 Nascent Elementium Spikes from the ground of the Mo'grosh Stronghold.", progress = "Did you tear up the spikes?", completion = "Shame that these half-formed things are too brittle and warped to be used for some weapons of our own. But it's thanks to you that we had the chance to get them out before they set. I'm not about to complain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27078] = { id = 27078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'kresh", description = "The ogre left to watch over these crude fools goes by the name of Gor'kresh. He's big enough to boss even these brutes around, and cunning to boot. Never assume an ogre's stupid, that's when they'll get you.\n\nIf you take him out, we'll show the Twilight's Hammer that Loch Modan isn't a stepping stone for them. Stand strong against Gor'kresh and drive these fools back into the highlands!", sourceObjective = "Defeat Gor'kresh.", completion = "You've done it! We may not have stopped the cult dead, but we've shown them we're not easy pickings and given them a welt to prove it.\n\nTake this with my gratitude, and try not to blush if anyone in Thelsamar calls you \"hero\"!", sourceObjectiveStatus = "unverified-source-field" }
quests[27082] = { id = 27082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Dirty", description = "Have you seen the huge lumbering ettins roaming the forests? Cursed things came from Gilneas. Now they wander the land searching for their next juicy meal. We've managed to subjugate and utilize some of them to haul our wagons, but the others... well, they must be killed!\n\nUnfortunately, we can't spare any soldiers to do the job. That's where you come in, {class}!\n\nI have a plan, but it's going to require some materials. Head out into the forests around this base and collect diseased beast organs.", sourceObjective = "Collect 8 Diseased Organs from Giant Rabid Bears and Rabid Worgs.", progress = "We are Forsaken! This is how we do it, {class}.", completion = "Excellent! Now to prepare the \"meal.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[27083] = { id = 27083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Forsaken that you are a hero of the first battle of Andorhal.  Koltira has requested your presence immediately.", sourceObjective = "Report to Koltira Deathweaver at Andorhal in Western Plaguelands.", completion = "Thassarian and the humans made their move.  I thought I had an agreement with Thassarian... but I suppose this will do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27084] = { id = 27084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farmers' Militia", description = "The battle started when they attacked us from the rear.  I let my guard down, and a group of poorly-armed farmers and militiamen swung into our flank from the Writhing Haunt.\n\nThey may be weak, but unchecked, they threaten to overwhelm us with their numbers.\n\nLindsay's pet abominations can handle the melee combat.  You take this collar, stay in the rear, and use it to release my ebon gargoyle upon these farmers.", sourceObjective = "Use the Ebon Gargoyle Collar on 6 Provincial Militiamen within Andorhal.", completion = "Merely a dent in their numbers... but the sight of their fellow men falling from the skies surely weakened their resolve.", sourceObjectiveStatus = "unverified-source-field" }
quests[27085] = { id = 27085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Troops", description = "While it is true that these farmers threaten to overrun us, we still cannot forget about the Alliance's main forces.\n\nTravel west into Andorhal and slay the human soldiers that are fighting with our deathguards.  We need all the help we can get.", sourceObjective = "Slay 15 Andorhal Defenders.", completion = "You fight well, {name}.  I wish I had your ability... and your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27086] = { id = 27086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "To the west, deep within Alliance-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The humans won't stand a chance.", sourceObjective = "Slay 3 Andorhal Force-Commanders.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Thassarian, for honor and for Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27087] = { id = 27087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay Ravensun, Revealed", description = "I was informed that that worthless woman, Lindsay Ravensun, would be here to support me in this battle, but so far, she's done nothing but brood within the basement of the greathall behind me.  All the better, I suppose.  She was a bit of a distraction.\n\nStill, I cannot and will not stand for insubordination.  Find her, and bring her to me.", sourceObjective = "Report to Lindsay Ravensun at Andorhal in Western Plaguelands.", completion = "You won't be taking me anywhere, {name}.\n\nWhile Koltira prances about with his playmate, Thassarian, I plan to win this battle.  Then I'll make Koltira suffer for his weakness.\n\nDon't believe me?  Fine, I'll let you in on a little secret...", sourceObjectiveStatus = "unverified-source-field" }
quests[27088] = { id = 27088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Only Poisonous if You Ingest It", description = "Take this cage, {class}. I've placed inside it one of my own mutant bush chickens, with a few slight modifications. Within the butt of this bush chicken is a stick of dynamite laced with gunk from the diseased organs you brought me.\n\nTake the cage out into the surrounding forest and locate the wandering forest ettin. Release the chicken and sit back as my masterwork does its job. The ensuing explosion should be sufficient to kill the ettin or greatly weaken it, allowing you to finish it off.", sourceObjective = "Use the Mutant Bush Chicken to kill the Forest Ettin.", completion = "<Apothecary Wormcrud laughs maniacally.>\n\nWas there ever any doubt? An ettin is no match for science!", sourceObjectiveStatus = "unverified-source-field" }
quests[27089] = { id = 27089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ace in the Hole", description = "You have no idea how difficult it was to stay disguised while I watched Koltira let this war slip away from us.  Even now, those infernal farmers threaten to overwhelm us.  All because he refused to slay a friend.\n\nTake my val'kyr again, {name}.  With her by your side, kill these farmers, convert them to Forsaken, and mobilize them.  Then take a group of them into Alliance-held western Andorhal and hunt down this death knight, Thassarian.\n\nWe will win this war yet.", sourceObjective = "With the Enthralled Val'kyr by your side, kill 5 Frightened Provincial Minutemen, then use your Call to Arms ability to turn them into Forsaken Troopers. Then find Thassarian in western Andorhal.", completion = "This is the body of Lurid, Thassarian's trusted knight.  With Thassarian nowhere to be found, it would seem that the Alliance forces have withdrawn.\n\nThe Forsaken have won the battle for Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27090] = { id = 27090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andorhal, Once and For All", description = "Sylvanas will want to know about Thassarian's departure from Andorhal.  You resolve to return to the Forsaken-held side of town.", sourceObjective = "Report to Lady Sylvanas Windrunner at Andorhal in Western Plaguelands.", completion = "See?  All it took was a little help from the val'kyr.  These creatures are turning to be much more helpful than I had first thought.\n\nNow, on to other matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27091] = { id = 27091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge!", description = "And now, it is time for your first lesson.\n\nI will show you a  great way to start combat, {name}. By seizing the initiative and charging in, you can stun your opponent and give yourself the upper hand.\n\nOnce our lesson has ended, find a training dummy and practice your new skill.", sourceObjective = "Learn Charge from Delios. Locate a Training Dummy outside the Sunspire and practice using Charge.", completion = "I think you've mastered the basics of the charge, {name}. Don't forget to return when you need more training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27092] = { id = 27092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm in the Catacombs", description = "Don't worry about me, {class}. I've uncovered the Twilight's Hammer plot. They've been stealing and stockpiling explosives coming into Stormwind harbor. Somehow, they've gotten access to the catacombs underneath the Cathedral of Light. I've heard talk of someone called \"The Black Bishop.\"\n\nThere's no time to warn the guard, {name}! You've got just minutes to get into the catacombs and disarm that bomb. Go! Now! Or THOUSANDS of PEOPLE will DIE!", sourceObjective = "Enter the Cathedral of Light and descend into the catacombs below. Slay the Black Bishop and disarm the Pile of Explosives nearby.", progress = "<Dark magical runes cover the surface of the explosives, pulsing with increasing intensity...>\n\nYou've got to find the Black Bishop!", completion = "<3 ... 2 ... 1 ...>\n\n<You wet your fingers and snuff out the fuse. The cathedral is saved!>\n\n<Underneath the powder kegs you find a heap of notes and papers. Apparently the cultists were trying to destroy the evidence behind them.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27093] = { id = 27093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Darkness", description = "Some would say that we are lucky to be alive. Those people would be idiots. At least had we died we would not have had to face the Warchief's wrath. Alas, what's done is done! Now we must attempt to regain our lost honor.\n\nThe third ship in our fleet sank off the coast of the Skittering Dark, northwest of here. Those that made it to shore quickly found themselves swarmed by the giant spiders of the area and encased in webbing.\n\nIf there are survivors we must free them! Go, {name}! To the Skittering Dark!", sourceObjective = "Rescue 6 Orc Sea Dogs from the Skittering Dark.", completion = "Lok'tar, {name}! Once the ale wears off my orcs will be ready!", sourceObjectiveStatus = "unverified-source-field" }
quests[27094] = { id = 27094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper into Darkness", description = "The Skitterweb matriarch is nearby! You can put an end to the Skitterweb menace by killing her!\n\nFind the brood mother at the end of the cave in the Skittering Dark and destroy her!", sourceObjective = "Kill the Skitterweb Matriarch.", progress = "You killed the Skitterweb matriarch?", completion = "You rescued our orcs and killed the Skitterweb matriarch? We owe you a great debt of gratitude. You've saved us all from certain execution, {name}. I'm sure we can rouse these drunken idiots now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27095] = { id = 27095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skitterweb Menace", description = "Vengeance is all consuming, {name}! Our third ship sank off the coast of the Skittering Dark, northwest of here. The men that made it off that boat were either captured or killed by the Skitterweb spiders of the region. For that, the spiders must die! ALL OF THEM!\n\nTravel to the Skittering Dark and crush those insects!\n\nBe on the lookout for their matriarch. Perhaps if we find her we can end this menace forever!", sourceObjective = "Kill 12 Skitterweb Spiders.", completion = "The root of this evil must be found and destroyed! The Skitterweb matriarch must be nearby. No doubt hiding in the nearby cave!", sourceObjectiveStatus = "unverified-source-field" }
quests[27096] = { id = 27096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs are in Order", description = "<Admiral Hatchet hands you an envelope sealed with the mark of the Horde.>\n\nThis is your commendation letter. It's the least I could do for you given the circumstances.\n\nReturn to Lady Sylvanas Windrunner with the letter and inform her of our status. Let her know that we will be ready to march on her command.\n\nGoodbye, {name}. You are an excellent soldier.\n\nNortheast, <lad/ma'am>. To Forsaken High Command!", sourceObjective = "Deliver the Admiral's Commendation Letter to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", progress = "And the orcs?", completion = "<Sylvanas raises an eyebrow.>\n\nSo the orcs are in order?\n\n<Sylvanas reads the commendation letter.>\n\nRecovered their supplies? Killed a dozen worgen? Toppled an ettin? Freed their soldiers and destroyed the Skitterweb matriarch?\n\nI say this rarely, {name}, but I am impressed. Perhaps your ability matches your aspirations. We shall see, for now you will be tested!", sourceObjectiveStatus = "unverified-source-field" }
quests[27097] = { id = 27097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Forsaken", description = "Fenris Isle stands defiantly at the heart of Lordamere Lake - a cruel memory of a time long since passed.\n\nThough no longer infested by gnoll vermin, a new threat has emerged.  Human refugees, driven from their holdings in Hillsbrad, have fled to Fenris Isle in hopes of escaping defeat at our hands. A critical error on their part.\n\nYou are to take Agatha with you to Fenris Isle and slaughter all humans. She will raise the fallen as Forsaken, bolstering our forces in the process.\n\nDo not fail me, {name}.", sourceObjective = "Raise 15 Forsaken by killing humans on Fenris Isle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27098] = { id = 27098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lordaeron", description = "Ride with me to the Sepulcher, {name}. There are many things I wish to discuss with you. It is imperative that you understand the history of Lordaeron and the plight of the Forsaken.", sourceObjective = "Accompany Lady Sylvanas Windrunner to the Sepulcher in Silverpine Forest.", completion = "Do you now understand the importance of our mission here? Crowley and his Alliance dogs must be stopped!", sourceObjectiveStatus = "unverified-source-field" }
quests[27099] = { id = 27099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Escape", description = "You must strike at their leaders, {name}. You will find them holed up in the old keep. Battle your way inside and find the holdouts! Turn them for your queen!\n\nNone shall escape the mighty grasp of the Forsaken!", sourceObjective = "Find the Refugee Leadership inside Fenris Keep.", completion = "It would seem that Crowley is more formidable than I anticipated. Still, he is a man - flesh and bone - full of secrets. Secrets that I know all about...\n\nYou have served me well, {name}. I could use someone of your ability at the Sepulcher. I have a plan to deal with Crowley and his insurgents once and for all. Will you help?", sourceObjectiveStatus = "unverified-source-field" }
quests[27100] = { id = 27100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Research", description = "The book you found appears to detail some form of research carried out by a member of the Twilight's Hammer.\n\nIt deals with the oozes in some way, but there are multiple pages missing.\n\nPerhaps if you found additional notes you might be able to make sense of it.", sourceObjective = "Obtain 4 Twilight Research Notes from Mercurial Oozes in the Upper Silvermarsh.", progress = "<You scroll through the notes, trying to put them in order.>", completion = "The notes deal with High Cultist Maziel's research on the elemental properties of quicksilver.\n\nHis obsession with the subject borders on the insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[27101] = { id = 27101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziel's Revelation", description = "The notes continue Maziel's rambling research into the properties of quicksilver and mercurial oozes.\n\nHe appears to have made a major discovery.  He mentions hiding his journal in the Lower Silvermarsh to the southwest.", sourceObjective = "Find Maziel's Journal at the Lower Silvermarsh in Deepholm.", completion = "Maziel's journal appears to be undamaged by the mercury.", sourceObjectiveStatus = "unverified-source-field" }
quests[27102] = { id = 27102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziel's Ascendancy", description = "Maziel's journal chronicles a ritual of ascendancy that would transfigure his body to one of pure quicksilver.\n\nThe ritual would take place in the cave near the Lower Silvermarsh, where Maziel would feed upon the mercurial oozes until achieving full strength.\n\nPerhaps it is not too late to put an end to his madness.", sourceObjective = "Slay Maziel inside the Silverlight Cave in Deepholm.", completion = "You've disposed of an enemy before he could grow more powerful.  By eliminating Maziel you've also ensured that his powers will not be used against the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[27103] = { id = 27103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of the Felvine", description = "The satyr Alzzin the Wildshaper has exerted his corrupt dominion over this part of Eldre'Thalas.  The Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin. It may be the key to purify this ancient place.\n\nWhen the great satyr falls, capture whatever essence of the Felvine you can.  Seal it in this Reliquary of Purity, and bring it to me.\n\nGood luck, and Cenarius' speed.", sourceObjective = "Use the Reliquary of Purity to capture a Felvine Shard.", progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.", completion = "You have done well, {class}, and for that I am forever in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this gold as a token of my enduring gratitude.  If we ever cleanse Dire Maul, know that you will be welcomed here as a hero. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27104] = { id = 27104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alzzin the Wildshaper", description = "The monster responsible for the ruin you see before you is called Alzzin the Wildshaper. To reach him, however, you will need to also slay Zevrim Thornhoof, the satyr who currently holds the still noble ancient Old Ironbark in his grasp.\n\nOnce Ironbark is free, he will help you make an entrance into Alzzin's domain. Enter and slay him without mercy, for there is no other way.", sourceObjective = "Kill Zevrim Thornhoof and Alzzin the Wildshaper.", completion = "Ah, very well done indeed. You've made an old spirit very happy this day. You deserve proper thanks for the risks you've taken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27105] = { id = 27105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Guest", description = "You will find that Dire Maul is filled with many nature and arcane elementals. Somehow, a water elemental has found its way into this area. Please gather its essence and take it to me. I am curious as to how one of their kind got here, and what sort of agenda it may have against the natural elements of Eldre'Thalas.", sourceObjective = "Collect the Hydrospawn Essence.", progress = "Do you carry the essence, or did the task prove too difficult?", completion = "It is very troublesome that a water elemental was here, let alone one that powerful. Take this as my thanks for your efforts. I must examine this essence for any knowledge it may contain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27106] = { id = 27106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Villain Unmasked", description = "<You find a complete list of all the Twilight's Hammer cultists in Stormwind.>\n\n<More importantly, you discover a letter from Major Samuelson to his compatriots outlining this entire scheme. The Prince was right: Samuelson is the real villain here, using his connections as commander of the city guard to disguise cult activity.>\n\n<It's time to return to Stormwind Keep and bring Samuelson to justice!>", sourceObjective = "Unmask and slay Major Samuelson in the Stormwind Keep Throne Room.", progress = "You have evidence incriminating Samuelson? Let's see what he has to say for himself!", completion = "Samuelson - corrupted by the Twilight's Hammer? This must have been going on for years. Right here in my very keep!\n\nI am grateful that you and my son were able to get to the bottom of this before my city was brought to harm. I've underestimated how much Anduin has grown - his command of the holy light just saved my life, if not the entire kingdom.\n\nAs for you - words alone can't do justice to your heroism this day. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27107] = { id = 27107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin The Thief", description = "Me take quick nap earlier and stupid fast imp take book! Dagg'thol need book to follow orders and Master need book to conquer! Gah!\n\nYou {race} help me get book from imp, and I give you shiny something. Go, imp right there to da left! KILL!!!", sourceObjective = "Convince Pusillin to give up the Book of Incantations.", progress = "{race} has book?", completion = "Now you watch Master use book to kill stupid trees and stupid goat men! YAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[27108] = { id = 27108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "Blood Elf Lethtendris has web to catch magic here. She use for herself, but Master want to use for good of whole world! You help get web from stupid elf and not only will Dagg'thol reward you, you see how Master use it way better!", sourceObjective = "Obtain Lethtendris's Web.", progress = "{name}, you have stupid elf's web?", completion = "This web have lots of magic! Master will be very happy now!\n\nAnd you make Dagg'thol happy, {race}. Take this so you believe how happy you make Dagg'thol!", sourceObjectiveStatus = "unverified-source-field" }
quests[27109] = { id = 27109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warped Defender", description = "The Ironbark and Warpwood were once the mighty protectors of Eldre'Thalas. Look at how they have fallen! Ultimately, their fate lies at the hands of myself and my fellow Highborne. We were reckless with our power, {race}.\n\nBut you, you can right the wrongs here! Venture forth and put Tendris Warpwood to rest. He was the mightiest and last defender of this area, and deserves spiritual release. Be wary, for if you do not dispose of the Ironbark Protectors prior to engaging Tendris, he will call them to assist.", sourceObjective = "Kill Tendris Warpwood.", completion = "Your work here was noble. Fret not, for Tendris' soul was crying to be put to rest. He is thankful.", sourceObjectiveStatus = "unverified-source-field" }
quests[27110] = { id = 27110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Madness Within", description = "This madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the five pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced from the demon's demise, attack and end him as well. Lay the spirits of this city to rest, adventurer, and make the Prince pay for his wrongdoings.", sourceObjective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", progress = "Be wary, adventurer. The Prince is... persuasive.", completion = "We thank you, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[27111] = { id = 27111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", sourceObjective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", completion = "You open the chest to find...", sourceObjectiveStatus = "unverified-source-field" }
quests[27112] = { id = 27112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Remains", description = "There are remaining beings here that pose a direct threat to us ever reclaiming this sacred city. Magister Kalendris and Illyana Ravenoak are both extremely dangerous and need to be disposed of as quickly as possible.\n\nExercise caution, for with there being so few remaining feeding off of Immol'thar's energies, they are likely to be stronger than they first appear.", sourceObjective = "Kill Magister Kalendris and Illyana Ravenoak.", completion = "Your dedication will make this all that much easier.", sourceObjectiveStatus = "unverified-source-field" }
quests[27113] = { id = 27113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shen'dralar Ancient", description = "Some beings here have miraculously managed to remain free of the darkness that runs so rampant. On the second story of the Court of the Highborne rests a Shen'dralar Ancient. Seek it out, it may hold a wealth of wisdom, perhaps even the secret to freeing Eldre'Thalas.", sourceObjective = "Speak to the Shen'dralar Ancient.", completion = "Our meeting is no coincidence, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27114] = { id = 27114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Taste Test", sourceObjective = "You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[27115] = { id = 27115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ando's Call", description = "You've done great work here, {name}. While you were out, that young Ando fellow was here looking for you. Said something about a metal bird.\n\nYou might want to go back to the shores of the Loch and see what he wanted.", sourceObjective = "Talk to Ando Blastenheimer.", completion = "It's working! My father brought it!", sourceObjectiveStatus = "unverified-source-field" }
quests[27116] = { id = 27116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winds of Loch Modan", description = "Father finished the Skystrider. It's amazing! Once we get the bugs worked out, I'm going to use it to fight for justice, just like you.\n\nI know you've got to move on, and help other people, being a hero and all, but how about a ride? I'm about to take the Skystrider on its first flight, and I'll be honored if you join me. I'll drop you off at Algaz Station.\n\nWhat do you say?", sourceObjective = "Ride the Skystrider to Algaz Station and then speak with Mountaineer Stormpike.", completion = "What in blazes WAS that? A flying mechanostrider?\n\nYou know what, I don't want to know. I'm just going to pretend that didn't happen, and we'll be all nice and businesslike.", sourceObjectiveStatus = "unverified-source-field" }
quests[27117] = { id = 27117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Strength", description = "Gandling has brought his lieutenant, the Ravenian, with him.  This lumbering brute is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find the Ravenian within a tower near the southern end of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", sourceObjective = "Kill the Ravenian within Andorhal.", completion = "Excellently done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27118] = { id = 27118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Broken Trap", sourceObjective = "A large, broken trap lies before you.  From the looks of it, the ogres have tried to repair the trap but to no avail.\n\nA hastily written note lies next to the trap, and strangely enough it details exactly how to repair it: just a few simple adjustments ought to do it.  Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.\n\nClearly, it would seem fortuitous that very few ogres know how to read.\n\nClearly.", sourceObjectiveStatus = "unverified-source-field" }
quests[27119] = { id = 27119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Ogre Suit", description = "If you're going to fight the king of the Gordok then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive.\n\nHow, you ask? I think I know! An ogre suit!\n\nI'll make you one if you bring me an Ogre Tannin from upstairs.  I'm not going anywhere like this...", sourceObjective = "Bring an Ogre Tannin to Knot Thimblejack.", progress = "Just get me that Ogre Tannin, and I'll whip you up an ogre suit that will fool Captain Kromcrush into thinking you're one of his men.", completion = "Yeah, this will do the trick.  Just a slip here, and tuck here... heh - this is going to work out just fine!  <A broad smile beams from the chained goblin's face.>\n\nHere you go, you're all set.  Remember- this isn't the most securely fashioned item in the world.  You'll have ten minutes of use before it falls apart, and then you're not going to fool anybody!  Try using it just before you approach him to make sure it lasts as long as you're going to need it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27120] = { id = 27120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Ogre Suit", progress = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me another Ogre Tannin, and I'll make you another ogre suit.", completion = "Here ya go {name} - put this thing on, and you'll have ten minutes to do whatever.  Good luck!\n\nOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!" }
quests[27122] = { id = 27122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fired Up and Not So Good To Go.", description = "Leave it to the Dark Irons to work with Ragnaros' toadies and worse. You can bet that insane Twilight's Hammer cult is behind the lot of this!\n\nTime to end their attacks on Ironforge once and for all. Oh, and tell Commander Cragfist what's happened here when we return; I'll need to work on getting the city and its good people back in order.", sourceObjective = "Slay Grand Ambassador Flamelash and inform Commander Cragfist in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27123] = { id = 27123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepholm, Realm of Earth", description = "I knew you'd heed our call, {name}.  When Deathwing was first defeated by the other dragon aspects, he retreated to Deepholm, the realm of earth.\n\nDeathwing's return to our world left a rift open between Azeroth and Deepholm.\n\nIf we don't mend the breach, this land will be torn asunder.\n\nWe're doing our best to contain the damage on this side of the rift.  Aggra will take you through the rift so you can help repair the damage from the other side.\n\nGet on her wyvern when you're ready.", sourceObjective = "Jump on Aggra's Wyvern and fly into the breach at the Maelstrom. Once you're on the other side, speak to Maruut Stonebinder.", completion = "You've arrived just in time, {name}.  All our resources are tied up keeping the rift stable.\n\nWe need someone like you to help us recover the fragments of the World Pillar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27124] = { id = 27124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from Guard Mol'dar!  Da king before you never listened, just like all da other kings since da old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  You find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", sourceObjective = "Speak to Guard Mol'dar in Dire Maul.", completion = "Wow... you ARE da true king! Old king never even ask about da gauntlet!\n\nLook - this mark on da gauntlet an old old OLD timey magic mark, older than da Gordok they say.  Well, I learn one thing as little ogre - how to make mark come to life and give power back to gauntlet!\n\nI do it for you, king!  Here, take da gauntlet and rule FOREVER!", sourceObjectiveStatus = "unverified-source-field" }
quests[27125] = { id = 27125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Gordok", description = "In Gordok society, their king is simply their strongest warrior. If anyone, ogre or otherwise, kills the current king, they are automatically hailed as the new one.\n\nThe new king receives tribute from any living guards, Stomper Kreeg, and Captain Kromcrush. Find and kill King Gordok while killing as few of their other leaders as possible, and not only will your reward be great, you will be able to use your power as king to halt the Gordok invasion without conflict!", sourceObjective = "Kill King Gordok.", completion = "Yes! I can see that you were indeed successful. You have received your tribute, the Gordok advance will exist no longer, and the Gordok are blissfully ignorant! This is a true winner's scenario, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27126] = { id = 27126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rush Delivery", description = "Peak Grindstone's team broke down somewhere out there to the west.\n\nThink you can make yourself useful for a change and rush some parts out to them, {race}?", sourceObjective = "Deliver the Catapult Parts to Peak Grindstone on the Fractured Front in Deepholm.", progress = "Are those spare parts you have there?", completion = "I can't thank you enough, {class}. Now, let's see if we can get this catapult moving again.", sourceObjectiveStatus = "unverified-source-field" }
quests[27127] = { id = 27127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fired Up and Not So Good To Go.", description = "Dark Irons? Cho'gall?! We'll show them what becomes of those who attack Orgrimmar.\n\nLet us attack! We'll hurl their limbless corpses into the magma they so adore.\n\nYou'll tell Blood Guard Kang what's happened here when we're done, yes? Doubtless I'll need to spend time organizing the repair of the city...", sourceObjective = "Slay Grand Ambassador Flamelash and inform Blood Guard Kang in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27128] = { id = 27128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Gordok", description = "You kill Gordok leader, you new ogre king. If you king, then ogre leaders like Kromcrush and Kreeg that survive pay you big tribute and you stop Gordok invasion. If you do that, then me very happy ogre and we take Dire Maul FOR DA HORDE!!!\n\nGo, little {race}! Kill ugly Gordok ogre king and maybe dis be new Stonemaul Hold! Yar!", sourceObjective = "Kill King Gordok.", completion = "Little {race} did it! Now Horde more powerful than ever! YAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[27129] = { id = 27129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own. Taking Dire Maul would be a major step in reclaiming Feralas for our people.\n\nYou can find Dire Maul to the southeast of here.", sourceObjective = "Speak to Furgus Warpwood.", completion = "Have you been in contact with a druid of the talon recently, {class}? I can feel the lingering presence of one.", sourceObjectiveStatus = "unverified-source-field" }
quests[27130] = { id = 27130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own before they set their sights on Camp Mojache. Perhaps we can even enlist his aid afterward to ensure we maintain our presence in Feralas with enemies on so many sides.", sourceObjective = "Speak to Furgus Warpwood.", completion = "Your face shows signs of desperate conflict. I honor your presence, brave {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27131] = { id = 27131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of the Highborne, it is an effort I must support for the good of Feralas. May the wind carry your spirit there with great swiftness.\n\nYou will find Dire Maul to the southeast.", sourceObjective = "Speak to Estulan.", completion = "I sensed your coming all the way from Dreamer's Rest. Your assistance would be most welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[27132] = { id = 27132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of his kind, it is an effort I must support for our own good. Please hurry, we need every foothold in Feralas that we can get.\n\nYou will find Dire Maul to the west.", sourceObjective = "Speak to Estulan.", completion = "I sensed your coming all the way from Camp Mojache. Your assistance would be most welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[27133] = { id = 27133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes in the Sky", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. I requested a druid of the talon to go there and scout it out. If he still lives, speak with him and he will act as your commander to stop the Gordok before they decide to attack.\n\nThat's an order, {class}.", sourceObjective = "Speak to the Druid of the Talon.", completion = "Speak softly, {name}. The Gordok may not be intelligent, but they are still dangerous warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[27134] = { id = 27134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre in the Field", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. If we eradicate them and take Dire Maul for the Horde, we will possess a heavily fortified seat of power in this region with numerous artifacts to sweeten the deal. I sent in a small army of Stonemaul Ogres inside earlier - if any have survived, speak with them and finish the job.\n\nThat's an order, {class}.", sourceObjective = "Speak to the Stonemaul Ogre.", completion = "These ogres no pushovers. I need you help me finish Orhan's task, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27135] = { id = 27135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something that Burns", description = "Alright, we need something that's going to make the compound go, \"Boom\"!\n\nI'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental!\n\nHere, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.", sourceObjective = "Obtain the Burning Heart.", progress = "You have the heart yet?", completion = "Uh oh. Sounds like he wasn't very happy about the situation. How was I to know? I'm just an initiate after all.\n\nAnyway, I'll worry about Magmatooth later.", sourceObjectiveStatus = "unverified-source-field" }
quests[27136] = { id = 27136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Energy", description = "It's taking every ounce of our power to keep this realm stable in the absence of the World Pillar.\n\nAs shaman we can tap directly into the energies of the elementals that inhabit Deepholm and use them to heal the damage that the rift is causing.\n\nTake this totem and place it on the ground outside.  Any energized geodes or lodestone elementals destroyed in its proximity will fill it with the energy we require.", sourceObjective = "Destroy 8 Energized Geodes or Lodestone Elementals near the Depleted Totem.", completion = "Thank you, {name}.  We need all the power we can muster to keep Deepholm stable.", sourceObjectiveStatus = "unverified-source-field" }
quests[27139] = { id = 27139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hobart Needs You", description = "Heya, boss, Hobart Grapplehammer's wants to speak with you. He says it's a matter of some urgency.", sourceObjective = "Speak with Hobart Grapplehammer at the Town-In-A-Box on the Lost Isles.", completion = "There you are, my boy. I have something very important for you to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27140] = { id = 27140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexi's Gambit", description = "I require your assistance, {class}. Find the undead mage Vectus and the warrior Marduk deep within here. They run the scourge's plagued dragon operation and must be destroyed.\n\nPlace this Gambit in the viewing room where they are located. Hopefully, it will react with their forces and utterly destroy them!\n\nOh, defeating Vectus and Marduk afterward shouldn't be a problem.  Right?", sourceObjective = "Place the Gambit in the Viewing Room and slay Vectus and Marduk.", progress = "Are they defeated?", completion = "You did it!  They are defeated!  And the Gambit... did it work?\n\nVery interesting. You've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27141] = { id = 27141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploding Through", description = "What a find!\n\nRight here... exactly where my notes predicted it would be.\n\nWith any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise.\n\nThat's right, {name}. It's not just a myth. I believe it truly exists.\n\nI'll explain more later. For now, just give me a hand with these explosives.", sourceObjective = "Assist Harrison Jones at the Khartut's Tomb.", completion = "Shake it off, kid.\n\nHappens to me all the time...", sourceObjectiveStatus = "unverified-source-field" }
quests[27142] = { id = 27142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich, Ras Frostwhisper", description = "One of Kel'Thuzad's most trusted students oversees the operations in Scholomance. You must confront the lich, Ras Frostwhisper, in his lair. The door to his chamber is adjacent to the viewing room.\n\nDestroy him, {name}. Leave no trace of his existence so that he may never again bring such horrors into our world.", sourceObjective = "Destroy Ras Frostwhisper.", progress = "You carry the burden of ten thousand restless souls, {name}.", completion = "Ten thousand souls cry out in unison, {name}! You have struck a mortal blow to the Scourge and their masters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27143] = { id = 27143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barov Family Fortune", description = "Within Scholomance lays the Barov family fortune. Alexi and I are the last two Barovs in existence.\n\nHowever, I am the only living Barov, so our family's vast empire belongs to me! Find me the deeds to Caer Darrow, Brill, Tarren Mill, and Southshore and I will repay you generously. The Barov estate will be reborn at long last!", sourceObjective = "Recover The Deed to Caer Darrow, The Deed to Brill, The Deed to Tarren Mill, and The Deed to Southshore.", progress = "Bow your head in my presence, {race}. I am a noble, after all, and you are a copperless peasant.", completion = "Excellent work, {race}. Alexi deserves nothing for his foolishness.", sourceObjectiveStatus = "unverified-source-field" }
quests[27144] = { id = 27144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reckoning", description = "Your performance was admirable, soldier.  You make the Forsaken proud, which is more than I can say for our general, Koltira Deathweaver.\n\nI intend to have a word with that death knight.  He has shamed himself and his cause.", sourceObjective = "Stand by as Lady Sylvanas Windrunner speaks with Koltira Deathweaver.", completion = "I have nothing against the Knights of the Ebon Blade, but Koltira needs to be reminded who he works for now.  His loyalty must lie with the Horde.\n\nOr, more specifically, the Forsaken.\n\nI wouldn't plan on seeing Koltira anytime soon.  Now that I have him... you can rest assured that any bonds he may have had with that Alliance scum will be thoroughly broken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27145] = { id = 27145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagued Hatchlings...For Now", description = "One of the 'projects' underway here is the plagued dragonflight. Thankfully, they're only hatchlings right now, but if we wait much longer they will become one of the scourge's most powerful weapons and a major threat to all of Azeroth, especially my family's land!\n\nSlay ten of their whelps and be sure to take care of Rattlegore as well. He is in the small space beneath where the whelps are housed and prepares supplements to catalyze their growth. Hurry...before they get any bigger!", sourceObjective = "Kill 10 Plagued Hatchlings and Rattlegore.", progress = "Take out those plagued hatchlings before they grow!", completion = "Well done, {name}!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!", sourceObjectiveStatus = "unverified-source-field" }
quests[27146] = { id = 27146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doctor Theolen Krastinov, the Butcher", description = "Doctor Theolen Krastinov is responsible for the deaths of thousands. His nickname, The Butcher, is well earned for the atrocities he takes joy in executing. He must be punished, justice must be meted out.\n\nFind him and exact upon him the agony he has inflicted upon countless innocents, including me and my husband. Once he is destroyed, burn our remains. Turn them to ashes, {name}. Release our grieving souls.", sourceObjective = "Destroy Doctor Theolen Krastinov, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff.", progress = "The Butcher must be stopped!", completion = "I can feel my spirit healing, {name}. You have done my husband and I a great service.", sourceObjectiveStatus = "unverified-source-field" }
quests[27147] = { id = 27147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos the Herald", description = "With blood, Kirtonos may be summoned. It is with blood, then, that Kirtonos must be destroyed.\n\nWithin the Chamber of Summoning, you will find a brazier, upon which you shall place a drop of your own blood. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.", sourceObjective = "Destroy Kirtonos.", completion = "With the death of Kirtonos, a chapter in the horrible tale of Scholomance comes to a close. You have my deepest, everlasting gratitude for your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27148] = { id = 27148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "School's Out Forever", description = "Darkmaster Gandling serves as headmaster of Scholomance, and is therefore responsible for countless deaths at the hands of his students. For that he must be punished.\n\nHe will not come out easily. Lure him out by slaying his six professors whose rooms connect to the Headmaster's Study. Be wary, for when the last falls he will come, and he will come infuriated with vast magic backing his assault. Don't let him make it out of here alive.", sourceObjective = "Kill Darkmaster Gandling.", progress = "Gandling's school of horrors must be put to a permanent end.", completion = "Without a headmaster, the school will descend into chaos. It will not put forth any more of its vile 'students' into the field. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27149] = { id = 27149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "School of the Damned", description = "Greetings! As you can see, the Western Plaguelands is very nearly free of the last remnants of the scourge. However, their school of necromancy, Scholomance, still sits full of lost young souls training to become scourge sorcerers! Our work here will be for naught if we do not stop this flow of fresh, not to mention very powerful, necromancers.\n\nTravel southeast to Scholomance and find Weldon Barov. He is the last living member of the Barov line that once owned all these lands and is our current contact.", sourceObjective = "Speak to Walden Barov in Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27150] = { id = 27150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "It's likely that the battle for Andorhal will start up again soon.  In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle.  I don't doubt that they'll have some work for you.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.It's likely that the battle for Andorhal will start up again soon. In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle. I don't doubt that they'll have some work for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27151] = { id = 27151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taelan Fordring's Legacy", description = "Greetings.  How do you do?  My name is Daria.\n\nI am one of the priests in charge of preserving the peace here in Hearthglen.  One of my duties involves maintaining the tower down the trail to the southeast of Hearthglen.  This particular tower is of personal importance to the Highlord.  It's the place where his son was killed.\n\nWith the recent incursion of gnolls, however, maintenance of the tower has grown difficult.  Will you help me rid the trail of some of these gnoll vandals, so I can do my duty?", sourceObjective = "Kill 10 Redpine Looters.", completion = "I must admit, {name}... I have been using my mind vision spell to keep tabs on you.  And I must say... the number of gnolls you found on the trail is truly staggering!", sourceObjectiveStatus = "unverified-source-field" }
quests[27152] = { id = 27152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Behavior... Even For Gnolls", description = "Allow me to concentrate for a moment.\n\n<You feel Daria's mind vision travel elsewhere, then it returns to you.>\n\nFurther down the trail, south of Taelan's Tower, the gnolls have carved out a small meeting area to the east of the main road.  Something is happening there... I'm not certain what.  We should investigate.  I will look for anything out of the ordinary... you just protect yourself.", sourceObjective = "Investigate the gnoll hideout along the trail to Hearthglen in Western Plaguelands.", completion = "Gnolls and necromancy... what a surprise!  And I thought that, here in the Western Plaguelands, we had put these dark days behind us.\n\n<You sense Daria's eyes focusing on something on the ground.>\n\nWait... what is THAT?", sourceObjectiveStatus = "unverified-source-field" }
quests[27153] = { id = 27153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good People of Hearthglen", description = "See those reagents over there?  And these supplies right here?  Those belong to the Argent Crusade.\n\nGnolls are known for thievery, but as far as I know, Hearthglen hasn't had any incursions since the Redpine came.  Very suspicious.\n\nI know a few helpful folks within Hearthglen: Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus.  All can be trusted, and are well-connected.  Question them, to find out if they know anything about these lost supplies.", sourceObjective = "Speak with Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus within Hearthglen.", completion = "Did you notice, {name}?  Many names were mentioned, but one name was mentioned far more than the others.\n\nBisp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27154] = { id = 27154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bagging Bisp", description = "Magus Bisp is one of Hearthglen's most preeminent arcanists.  To imagine that he would be interacting with gnolls... and dabbling in necromancy?  Unthinkable.\n\nYou'll find him atop the tower near Hearthglen's main gate.  Hopefully he'll have an explanation for all of this.  If not, well... I wouldn't go to the top of that tower unprepared, {name}.", sourceObjective = "Speak with Magus Bisp atop the mage tower in Hearthglen.", completion = "I suppose that we can take his aggression as an admission of guilt.  You alright, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27155] = { id = 27155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Yourself In", description = "So... you killed a member of the Argent Crusade, inside of Hearthglen.  Usually that's not smiled upon, even in self-defense.\n\nI recommend you come back to Mardenholde Keep, and turn yourself in to Highlord Fordring.  Hopefully he will hear you out, and will be sympathetic with your situation.  I hope I haven't gotten you in any trouble.", sourceObjective = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", completion = "I'm already aware of your actions, {name}.  I welcome you into my town, give you my blessing, and what do you do?\n\nYou slay the traitor that we've been hunting down for weeks.  Well done.  Your heroism is budding much earlier than even I had anticipated.", sourceObjectiveStatus = "unverified-source-field" }
quests[27156] = { id = 27156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's About Time!", description = "Finally!  You're here!  Get to work!\n\nMy men have been sparring with these wooden practice dummies for far too long.  Sure, you can learn how to swing a sword by practicing with a dummy, but real combat requires a real combatant.\n\nHmmm... I had asked for them to send me someone imposing, but I suppose a skinny-armed {race} {class} will have to do.\n\nNow get in there and teach my men how to fight!", sourceObjective = "Challenge and defeat 7 Hearthglen Trainees.", progress = "I'm not paying you to talk to me.  I'm paying you to talk with my soldiers... and then fight with them.", completion = "I'm just looking over my paperwork here, and it says that we were expecting a FEMALE {race} {class}.  You're not, umm...\n\n\n\nNever mind.  It would appear that you are not the person that I originally hired, but you did a good job.  So I'm going to pay you anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[27157] = { id = 27157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drudges... <Sigh>", description = "Say, I never caught your name.  {name}?  Pleased to meet you, {name}.\n\nI've got one more problem that needs fixing, and you have a look about you that just screams \"I'm a problem-fixer\".\n\nThere's a small mine on the northern edge of Hearthglen, where we get most of the ore that the town needs.  My drudges who work the mine normally do a decent job.\n\nUnfortunately, it seems that a larger-than-average spider has taken up residence within this cave.  Think you can clear things up for me?", sourceObjective = "Kill Shadril within the mine inside Hearthglen.", progress = "I need to get those drudges back to work.", completion = "Nice work!  In retrospect, I'm glad that other {race} {class} never showed up... you've proven to be all the help I need.", sourceObjectiveStatus = "unverified-source-field" }
quests[27158] = { id = 27158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the time for the Alliance to start to retake Lordaeron.\n\nSpeak with the gryphon master, Bibilfaz Featherwhistle, when you are ready, and he will put you on the first flight out there.", sourceObjective = "Report to Thassarian within Andorhal in Western Plaguelands.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27159] = { id = 27159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge First... Horde Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Koltira, leads the Forsaken forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Koltira well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Forsaken will have to wait to taste our wrath.", sourceObjective = "Slay 15 Desiccated Scourge within Andorhal.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, {name}, when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[27160] = { id = 27160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Machines", description = "Dried-up Scourge... weak.  Abominations... strong.\n\nWe defeat strong abominations... we win war.", sourceObjective = "Destroy 6 Opengut Behemoths in Andorhal.", completion = "Abominations... strong.\n\n{name}... stronger.", sourceObjectiveStatus = "unverified-source-field" }
quests[27161] = { id = 27161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Lang passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", sourceObjective = "Use Lang's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, {name}.", completion = "These grenades are all explosives, nothing more.  I may not be a goblin engineer... but I still understand the value of being able to just explode things every once in a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[27162] = { id = 27162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", sourceObjective = "Kill Darkmaster Gandling within Andorhal.", completion = "Excellently done, {name}.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27163] = { id = 27163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Strength", description = "Gandling has brought his lieutenant, Rattlegore, with him.  This clattering horror is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find Rattlegore within an old town-hall building, near the center of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", sourceObjective = "Kill Rattlegore within Andorhal.", completion = "Excellently done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27164] = { id = 27164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", sourceObjective = "Kill Araj the Summoner. You may use Lang's Hand Grenades to destroy Stickbone Berserkers.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  That gnome has done his part in winning this war.  As have you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27165] = { id = 27165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory, For Now", description = "The Alliance are victorious, and our forces are still strong.  Military strategy dictates that we attack the Forsaken now, while they are recovering and unaware.  I made a deal, however...\n\nWe will wait.  We attack Koltira and his troops when the time is right.  In the meantime, speak with Ginny Goodwin and take a flight to the Chillwind Camp, to our south.  Commander Ashlam Valorfist will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", sourceObjective = "Report to Commander Ashlam Valorfist at Chillwind Camp in Western Plaguelands.", completion = "Word arrived shortly before you did, {name}.  With the Scourge ejected from Andorhal, we are one step closer to retaking Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[27166] = { id = 27166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Fletch!", description = "We must always be prepared for battle, {name}.  Whether that battle is against the Forsaken in Andorhal, against the Scourge in the east, or against some yet-unknown foe is unknown.  What is known, is that we must be ready.\n\nWe are low on arrows.  I can obtain the shafts and heads, but I still need feathers.  The birds that circle to the northwest typically molt this time of year.  Would you mind traveling out into the field and gathering some of these feathers for our camp?", sourceObjective = "Obtain 9 Brownfeather Quills.", progress = "It's good to see you back, {name}.", completion = "I will have my fletchers get to work on these.\n\nI'm glad to see you being so useful right away, {name}.  Perhaps later I will have some more exciting tasks for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27167] = { id = 27167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mighty Hunger", description = "I hail from Westfall, far to the south... as do these men that travel with me.  We are farmers, and nothing more.\n\nI had been told that Lordaeron had been healed, and that it was ready for tilling.  However, this \"Commander\" now tells me that it's too dangerous to proceed.  He says that there's a war going on, and that the plaguelands still aren't healed.\n\nBefore anything else, I need to get some food in my men's stomachs.  Anything will do.  Bear seems to be plentiful.", sourceObjective = "Obtain 5 Sides of Bear Meat from Shaggy Black Bears in Western Plaguelands.", progress = "We've traveled a long way.  Anything you can spare would be appreciated.", completion = "You hunt like a true {class}.  Even if we can't set up our homesteads... at least we can still eat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27168] = { id = 27168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those That Couldn't Let Go", description = "Sorrow Hill, up the road to the northeast, was one of the first places that the Argent Crusaders and Cenarion Circle were able to heal.  The area is now freed of the Scourge.\n\nHowever, there are still many specters of the past that, for some reason, have not passed on into the next world.  They may be mourning, they may have unfinished business... or they may just be lost.\n\nTake my thurible and use it to douse them with holy incense.  One way or another, we will help them move onto the next plane.", sourceObjective = "Use the Holy Thurible on 12 Withdrawn Spirits in Sorrow Hill, and slay them if they react negatively.", completion = "Hopefully most of them passed on peacefully.  I thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27169] = { id = 27169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Blessing", description = "These farmers from the south wish to take these farms, but I can't let them enter the plaguelands unprepared.  Even with the Scourge gone, danger still looms in the form of the Forsaken.  No, we must be ready to fight... and that includes our new visitors.\n\nBefore doing anything else, however, I would recommend that you travel to Uther's Tomb, to the east, and place this tribute before his statue to ask for his blessing.  Speak with the priest that tends to the tomb when you are finished.", sourceObjective = "Enter Uther's Tomb, and use the Chillwind Tribute before his statue.", progress = "Uther was a great hero.  It is my honor to serve him, even after he has passed.", completion = "You and the humans at Chillwind Camp wish to re-take Andorhal?  I wish you luck.", sourceObjectiveStatus = "unverified-source-field" }
quests[27170] = { id = 27170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Crypt", description = "If you truly intend to move forward in this battle for Andorhal... well, perhaps I can help.\n\nTo the east lies a large crypt.  The bottom level of the crypt was once used for storage of weapons and armor... until the Scourge came.  Now that the undead have left, the weapons are free for the taking.\n\nMost of the weapons are probably rusted and rotten by now, but they will serve better than tunics and pitchforks.", sourceObjective = "Find the Weapons Crate at the bottom of the Crypt in Western Plaguelands.", completion = "Scattered all over the bottom level of the crypt, you find shattered crates that once held weapons and armor.\n\nIt appears that somebody got here before you did.", sourceObjectiveStatus = "unverified-source-field" }
quests[27171] = { id = 27171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed!", description = "As you turn around, you see the silhouettes of shambling skeletons on the stairs.\n\nThe undead aren't gone from this crypt.  They were lying in wait!  Furthermore, they appear to be armed with the weapons that you came looking for.\n\nYou'll have to escape from the crypt.  On your way out, you should gather as many pieces of equipment as you can.", sourceObjective = "Obtain 4 Time-Worn Breastplates and 4 Rusted Swords.", progress = "What happened at Uther's Tomb, {name}?", completion = "Attacked by ghosts?  Strange.  I suppose that crypt wasn't fully healed after all.\n\nYou just missed Thurman Grant... you remember, that oaf of a farmer that was here earlier.  He took his men with him and traveled to the nearest farm... against my orders.", sourceObjectiveStatus = "unverified-source-field" }
quests[27172] = { id = 27172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writhing Haunt", description = "The farmers traveled to the Writhing Haunt, an old farm to the northeast, across the river.  Someone needs to keep an eye on them.\n\nBring them those rusty weapons and armor you found.  We can't have them fighting with pitchforks.", sourceObjective = "Bring the Battered Weapons and Armor to Thurman Grant at the Writhing Haunt in Western Plaguelands.", progress = "Did Valorfist send you?  He doesn't know when to let up, does he?", completion = "Well, now that you're here, we'll gladly take that armor off your hands.\n\nYou can keep the weapons, though.  These men wouldn't know which end to hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[27173] = { id = 27173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Our Army", description = "I told Commander Valorfist that we could hold our own, and we intend to.  I had a little conversation with the death knight general, Thassarian, on my way over here.  We farmers plan to help in our own way.\n\nWe will take control of this farm, begin to cultivate the land... and then when the battle for Andorhal commences, we will attack the Forsaken from the rear.  They'll never expect it.\n\nFirst, we need to get rid of these Forsaken outriders.  Kill some, then return to me.", sourceObjective = "Kill 10 Forsaken Outriders.", progress = "My men need your help, {name}.", completion = "You fight well, {race}.  My men could stand to learn a few moves from an experienced {class} like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27174] = { id = 27174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "In fact, you might still be able to help train some of my men.  You probably noticed the abomination outside.  We initially tried to fight him, but he didn't fight back.  He seems to want to help out on the farm.\n\nTake a group of four settlers and challenge this abomination to combat.  He seems to be pretty tough, but with one of him and five of you, I think you'll have a chance at beating him.", sourceObjective = "Speak with Gory at the Writhing Haunt and challenge him to combat.", progress = "If we're going to help out in this battle for Andorhal, we need to learn how to fight.", completion = "We can handle things from here.  I thank you for your help, {name}.\n\nI assume that when we next meet, it will be in battle.  Take care of yourself until then.  We'll need all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[27175] = { id = 27175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "These men and women here at Chillwind Camp have noble goals, but their ultimate purpose is war.  I would like to offer you an opportunity to pursue more peaceful goals.\n\nAt the Menders' Stead, beyond war-torn Andorhal to the north, the Argent Crusade has joined forces with the Cenarion Circle.  Together, we work on healing this land from the plague that used to reign here.\n\nAre you interested in joining our cause, {class}?", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[27176] = { id = 27176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Disc", description = "The etching around the surface of this object indicates that it is of ancient origins, and yet no signs of wear can be detected.\n\nA hole on its edge, full of splintered wood, indicates that it is meant to be put atop a wooden staff of some sort.\n\nBefore showing this to Doctor Jones, you should find the other piece.", sourceObjective = "Obtain the Sultan's Staff, then use the Elaborate Disc to create the Shaft of the Stars.", progress = "Yes, {name}?", completion = "<Doctor Jones puts on his spectacles.>\n\nLet's have a look at this. Shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[27177] = { id = 27177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage Operation", description = "Between the Horde and the naga, our fleet has been decimated. We can't do anything to bring back the men who gave their lives to the sea, but sink me if I allow all of our supplies to be lost forever.\n\nSwim out to the Obsidian Breakers southwest of Highbank and retrieve our supplies from the wrecks and the ocean floor.", sourceObjective = "Retrieve 8 Recovered Supplies from Waterlogged Crates in the Obsidian Breakers.", progress = "How much were you able to recover?", completion = "Look at all this! You were able to recover more than I thought. We can outfit a whole squad of marines with this stuff.\n\nWe have the gear. If we only had some way to bolster our numbers here in the Highlands...", sourceObjectiveStatus = "unverified-source-field" }
quests[27178] = { id = 27178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Reinforcements", description = "They've come slithering up from the ocean depths, {name}. The naga. I think their intent is to reinforce the Bastion of Twilight, probably by heading inland via the Verrall river. We can't let that happen!\n\nTeach them that these shores are ours now, and send them scurrying back to the lightless depths.\n\nKill the Blackscale naga worming their way through the Obsidian Breakers!", sourceObjective = "Slay 10 Blackscale Myrmidons or Blackscale Seacallers.", completion = "That'll send 'em packing, {name}! Cho'gall won't be able to count on the naga to back him up in this fight. From here on out, it's just us versus the Twilight's Hammer.\n\n\n\n...And the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27179] = { id = 27179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Work", description = "This unfortunate pygmy was in the wrong place at the wrong time.\n\nAs you ponder his bad luck, you take notice of the symbols covering his shield - far too elaborate for pygmy scrawl.\n\nConfident that Doctor Jones will find such objects of interest, you set out to find more fragments like this one.", sourceObjective = "Collect 10 Ancient Tablet Fragments.", progress = "What'dya have there, friend?", completion = "These tablets are covered with titan writings. There's never-before seen information here, {name}!\n\nMissing pieces to an ancient puzzle...\n\nGood work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27180] = { id = 27180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dead", description = "A convoy of veteran troopers and Forsaken catapults were ambushed earlier today while attempting to cross Olsen's Farthing, directly south of here. It was a total loss: all troopers were killed and all catapults destroyed.\n\nBloodfang's pack was responsible for the ambush, though likely they have all fled back into the hills, preparing their next cowardly strike. Their day will come, but for now I want you to go to Olsen's Farthing and honor our fallen.\n\nRecover their Forsaken insignias.", sourceObjective = "Recover 6 Forsaken Insignias from Veteran Forsaken Trooper corpses.", progress = "Have you recovered the insignias?", completion = "I will see to it that these insignias are returned to the Undercity at once. The registrar will place their names in our records so that their sacrifice may never be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27181] = { id = 27181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excising the Taint", description = "It looks like a group of the ambushers stayed behind. Make them pay for their insolence! Kill all of the Bloodfang stalkers at Olsen's Farthing. For Sylvanas! For the Horde!", sourceObjective = "Kill 10 Bloodfang Stalkers.", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYou have avenged the fallen, {name}, but there is more to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27182] = { id = 27182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", sourceObjective = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", sourceObjectiveStatus = "unverified-source-field" }
quests[27183] = { id = 27183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsh Frog Legs", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", sourceObjective = "Collect 10 Marsh Frog Legs from Giant Marsh Frogs.", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew.", sourceObjectiveStatus = "unverified-source-field" }
quests[27184] = { id = 27184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", sourceObjective = "Collect 20 Unpopped Darkmist Eyes from Darkmist spiders.", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27185] = { id = 27185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting the Competition", description = "Look, I'm not about t' play games with ye. The Scarlet Crusade's Crimson Hammersmith was nothin' worth mentionin' before, but now that they're Balnazzar's Risen, the damned dreadlord has taught him t' make all sorts of powerful demonic weaponry.\n\nIt's simple. Find their blacksmithing plans and kill the Risen Hammersmith when he comes for 'em, so that we can make sure their army doesn't get their hands on demon armaments. They're powerful enough as it is!", sourceObjective = "Kill the Risen Hammersmith.", completion = "Nicely done, lad! Without them new weapons, they're just as easy t' kill as they were when they were alive!", sourceObjectiveStatus = "unverified-source-field" }
quests[27186] = { id = 27186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", sourceObjective = "Obtain Razorspine's Sword.", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[27187] = { id = 27187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the World a Favor", description = "Hyenas, on their best day, are a nuisance.\n\nThese foul specimens have a particularly nasty disposition, are riddled with all manner of disease, and are simply a blight on the face of dogdom.\n\nDo the world a favor and rid the deserts of Uldum of this mangy menace.", sourceObjective = "Kill 12 Mangy Hyenas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27188] = { id = 27188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", sourceObjective = "Gather information by defeating 10 Risen Husks or Risen Spirits.", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27189] = { id = 27189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, {name}. It may be our only hope.", sourceObjective = "Collect 9 sprigs of Witchbane near Witch Hill.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27190] = { id = 27190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", sourceObjective = "Plant the Witchbane Torch at the end of the dock and defeat the evil haunting Witch Hill.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, {name}. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[27191] = { id = 27191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry as an Ogre!", description = "You meet some people out here sometime. Nice people. Met an ogre once. Ogres get hungry just like me.\n\nI'll never forget what he said. He said \"Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you.\"\n\nSo I got him those fish and he ate 'em up. That's when I started too. The heads are the best part, all soggy-like.\n\nDon't crush those heads now. It makes them sad. Sad heads aren't good eating. Get me happy heads and I'll eat them and be happy too.", sourceObjective = "Collect 8 Mirefin Heads from Mirefin Murlocs.", progress = "Jarl's hungry. Just like that ogre.", completion = "Wonder what it's like to be an ogre. Big people have to eat more.\n\nOgres must be even hungrier than me. That doesn't sound very fun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27192] = { id = 27192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Fras Siabi", description = "Men as far as Kul Tiras spoke of the legendary Fras Siabi's premium tobacco. It was a delicacy enjoyed by every single person of importance that visited Stratholme. King Terenas, Uther the Lightbringer, Highlord Fordring...yes, they all enjoyed Siabi's specialty.\n\nSadly, Fras stayed in his shop when Stratholme was invaded, swearing on his life that the Scourge would never touch his tobacco. Venture forth and see if even one bit remains here...it is worth it's weight in gold, I assure you.", sourceObjective = "Recover a box of Fras Siabi's Premium Tobacco.", progress = "Did you find any?", completion = "Truly, you have uncovered the snuff of legends. It is nearly impossible to place a value on this historical tobacco.\n\nHere, have a few coins.", sourceObjectiveStatus = "unverified-source-field" }
quests[27193] = { id = 27193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek and Destroy", description = "<The Banshee Queen's voice invades your thoughts once more.>\n\nSearch the nearby farmhouses for Alliance stragglers. Keep an eye out for any information that could lead us to Crowley and Bloodfang. Seek and destroy all that would stand in your way, {name}!", sourceObjective = "Search the Farmhouses at Olsen's Farthing.", sourceObjectiveStatus = "unverified-source-field" }
quests[27194] = { id = 27194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cornered and Crushed!", description = "<The Banshee Queen speaks through your mind.>\n\nWe must act quickly, {name}. They mustn't be given the chance to flee. I am dispatching a squadron of my most powerful troopers to the Deep Elem Mine. I'm also sending the Horseman with them to ensure that nothing goes wrong. Meet him at the Deep Elem Mine, east of Olsen's Farthing, and CRUSH those rats.", sourceObjective = "Report to Master Forteski at the Deep Elem Mine in Silverpine Forest.", completion = "I s'pose we're to corner them first then crush, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[27195] = { id = 27195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Run", description = "The mistress has put me in charge of this lot. Our primary mission is to get in there, corner the rats, and kill 'em all, including Bloodfang.\n\nYou've done us a solid service in gettin' the information, {name}. Join in the glory and help us drive a sword through their miserable skulls!\n\nLet me know when you're ready and I'll call for the charge.", sourceObjective = "Escort Master Forteski through the Deep Elem Mine.", completion = "WHAT!?\n\n<Sylvanas shrieks.>\n\nCROWLEY!!!!!\n\nBastards. Those were some of our strongest soldiers. I have underestimated Crowley and Bloodfang for the last time. Clearly they are an enemy the likes of which we have never seen - willing to sacrifice their own to set a trap like this... unheard of in Alliance warfare.", sourceObjectiveStatus = "unverified-source-field" }
quests[27196] = { id = 27196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to Something", description = "This is remarkable work you've done! Especially for someone who hasn't taken my courses.\n\nThese tablets provide new information on several subjects.\n\nThey indicate that these obelisks are part of an enormous ancient mechanism that once kept this whole region masked from the rest of the world.\n\nThey also depict how to recharge the mechanism, which is where your Shaft of the Stars comes in...\n\nGet ready, {name}. We have some history to make!", sourceObjective = "Accompany Harrison Jones to the Chamber of the Stars.", progress = "Alright, now let's see what this staff can show us...", completion = "Would you get a load of this place!", sourceObjectiveStatus = "unverified-source-field" }
quests[27197] = { id = 27197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Alliance forces that you're a hero of the first battle of Andorhal.  Thassarian has requested your presence immediately.", sourceObjective = "Report to Thassarian at Andorhal in Western Plaguelands.", completion = "Word has it that you helped those farmers arm themselves.  Well, now they've initiated the attack without my order!  They've forced my hand.\n\nThe battle has resumed.  This time, we fight the Forsaken... and I fight Koltira, my old brother of the Ebon Blade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27198] = { id = 27198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Troops", description = "I'm no military expert, but this battle looks to be in our favor.  Our defenders are equally matched with their deathguards, but the farmers' militia has taken them by surprise from the rear.  For the Alliance!\n\nStill, we should all do what we can to make sure that we win.  Travel east into Andorhal and slay the Forsaken deathguards that are fighting with our men.  The sooner they die, the quicker we can re-take Andorhal!", sourceObjective = "Slay 15 Andorhal Deathguards.", completion = "You fight well, {name}.  I wish I had your ability... and your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27199] = { id = 27199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "To the east, deep within Forsaken-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The Forsaken won't stand a chance.", sourceObjective = "Slay 3 Deathguard War-Captains.", progress = "You will find them to the east, {name}.  Do not fail me.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Koltira, for honor and for Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27200] = { id = 27200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siren's Song", description = "She's still out there... Ophelia, the Siren of the Highlands! Her terrible song will lure you to the depths. I've vowed to stay behind and avenge my fallen crewmates, {class}. If you want to join me, just say the word.\n\nWe'll lash ourselves to the mast, we will. We'll shut our eyes. We'll stuff our ears with wax. And when her beautiful illusion drops... we'll strike.\n\nAre you in?", sourceObjective = "Slay Ophelia, the Siren of the Highlands.", completion = "She had me under her spell, {name}. I wouldn't have made it out of there alive if it weren't for you. Thank you!\n\nMaybe the rest of the Alliance fleet can finally anchor here in peace...", sourceObjectiveStatus = "unverified-source-field" }
quests[27201] = { id = 27201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'kyr Incursion", description = "The val'kyr were one of the Scourge's primary weapons.  Not only were they skilled in battle, but they could be used to convert corpses into Scourge minions.  To think that Sylvanas is stooping to such levels for the sake of the Forsaken...\n\nWe need to stop the val'kyr before they wipe us out and turn our army against us.  Slay as many as you can find.  And bring some of these minutemen with you.  If they've survived this long, then they must have some battle skill.", sourceObjective = "Kill 9 Lesser Val'kyr within Andorhal.", completion = "For every val'kyr you slay, you save dozens of our men... and prevent the Forsaken forces from growing.\n\nStill, they press on.  We may not win this battle after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27202] = { id = 27202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "Our militia has been nearly wiped out.  Only I and these few farmers remain.\n\nThose winged creatures... they took the bodies of our men and... and turned them into walking, undead corpses!  With every one of our men they took, they bolstered their own ranks.\n\nIt pains me to admit it, but you will need to fight them too, along with the deathguards and val'kyr.  As they did in life, they hunt in packs, so take some of my minutemen with you.", sourceObjective = "Kill 20 Forsaken Troopers within Andorhal.", completion = "You fought valiantly, but we're getting nowhere.  Every body that falls just fuels their forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[27203] = { id = 27203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maelstrom", description = "Thank the spirits you're here, {name}.\n\nWe're not sure how much longer we can maintain the rift in the Maelstrom.\n\nOur most powerful members, led by Thrall, are barely preventing the tear.\n\nLast I heard, our only hope was to go through the breach and attempt to stabilize it from the other side.\n\nI will conjure a portal.  Take it and report to Thrall as soon as you can.", sourceObjective = "Go through the Portal to the Maelstrom and speak to Thrall.", completion = "<Thrall's muscles strain as primal energy flows through him.  His eyes shift your way, acknowledging your arrival.>\n\nIt is good to see you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27204] = { id = 27204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aradne", description = "Our last hope of victory lies in defeating the val'kyr.  You've done well up until now... but you're only one <man/woman> and there are literally dozens of them raining destruction on the battlefield.\n\nOne enormous val'kyr sits atop the tower to our south... you can see her from here.  Perhaps if we eliminate her, the remaining val'kyr will dissipate.\n\nThis is our only hope.  Bring some of Grant's men with you.  You'll need their protection for this battle.", sourceObjective = "Slay Aradne atop the tower in western Andorhal.", completion = "I watched your victory from below.  Well-fought, but ultimately, it was for naught.\n\nThe val'kyr and the Forsaken press on; soon, they will overtake us.  We have lost Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27205] = { id = 27205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depravity of the Forsaken", description = "We nearly have this battle won, {name}.  I can taste victory.  The Forsaken never stood a...\n\nWhat the hell is that!?", sourceObjective = "Find out what Thassarian is looking at.", completion = "Val'kyr?  Koltira brought val'kyr to this fight?  Has he gone mad?\n\nNo, this is not Koltira's work.  This was Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27206] = { id = 27206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Andorhal", description = "Head south, to Chillwind Camp.  Tell Commander Ashlam Valorfist everything that happened here.\n\nMe?  I'm going west, into Tirisfal.\n\nMy battle's not over yet.  I've got an appointment with that harpy that calls herself a Banshee Queen... and I'm finding out what she did to Koltira.", sourceObjective = "Report the events of the battle of Andorhal to Commander Ashlam Valorfist.", completion = "Lost?  No... next, they'll be coming for Chillwind, I suppose.  This was a major strategic blow to the Alliance's plans for Lordaeron.\n\nVery well.  I will report the results of this battle to King Wrynn.  I don't expect him to be happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27207] = { id = 27207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Blows", description = "Is THAT what's behind the storms assailing my city?\n\nLet's push on. That towering windbag can bellow and blow all he likes, but this is the end of him. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", sourceObjective = "Slay Prince Sarsarun and inform General Marcus Jonathan in Stormwind City.", sourceObjectiveStatus = "unverified-source-field" }
quests[27208] = { id = 27208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadlord Balnazzar", description = "With the fall of the Scarlet Crusade, their disguised demon leader, Balnazzar, released the possessed body of Grand Crusader Dathrohan and went on a rampage, killing every remaining crusader here. He then used his necromantic power to raise them all as vile undead slaves.\n\nBalnazzar refers to his new army as the Risen. We cannot let him grow this army - they are extremely powerful and, unlike Arthas' Scourge, Balnazzar will not hold his forces back. Kill him while we still have a chance, {class}.", sourceObjective = "Kill Balnazzar.", completion = "It's good we stopped Balnazzar now. Before long, his army would have overtaken all of Stratholme, giving him a powerful center for his new unholy empire.", sourceObjectiveStatus = "unverified-source-field" }
quests[27209] = { id = 27209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Blows", description = "So. This is what evil lies behind the attacks on fair Thunder Bluff.\n\nLet us move forward. It is time to put an end to this abomination.\n\nTell Hamuul Runetotem what has happened here upon our return; I'll need to oversee the return of my people, repairs, and the like.", sourceObjective = "Slay Prince Sarsarun and inform Hamuul Runetotem in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[27210] = { id = 27210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors Among Us", description = "It's good to meet you, {class}. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", sourceObjective = "Confront 5 Deserter Agitators in Theramore.", completion = "Well done, {name}. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further.", sourceObjectiveStatus = "unverified-source-field" }
quests[27211] = { id = 27211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", sourceObjective = "Obtain the Deserter Propaganda from the boat at the end of the Theramore docks.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27212] = { id = 27212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", sourceObjective = "Distribute the Altered Leaflets to 6 Theramore Guards.", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!", sourceObjectiveStatus = "unverified-source-field" }
quests[27213] = { id = 27213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", sourceObjective = "Defeat Gavis Greyshield aboard the ship southeast of Theramore.", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, {name}. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the {class} who ended the deserter threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27214] = { id = 27214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", sourceObjective = "Report to Captain Wymor at Sentry Point.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27215] = { id = 27215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", sourceObjective = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?", sourceObjectiveStatus = "unverified-source-field" }
quests[27216] = { id = 27216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", sourceObjective = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27217] = { id = 27217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", sourceObjective = "Collect 4 containers of Thresher Oil from Murk Threshers beneath the Theramore docks.", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27218] = { id = 27218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", sourceObjective = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[27219] = { id = 27219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", sourceObjective = "Talk to Nat Pagle at Nat's Landing in Dustwallow Marsh.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part.", sourceObjectiveStatus = "unverified-source-field" }
quests[27220] = { id = 27220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim into the deep part of Tidefury Cove to the southwest. Let me know how it works!", sourceObjective = "Smear Pagle's Fish Paste, Extra Strength on yourself, then swim into Tidefury Cove.", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[27221] = { id = 27221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", sourceObjective = "Speak with Major Mills at the docks in Theramore.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", sourceObjectiveStatus = "unverified-source-field" }
quests[27222] = { id = 27222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", sourceObjective = "Use the mortars to defeat Tethyr.", completion = "Well done, {name}! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!", sourceObjectiveStatus = "unverified-source-field" }
quests[27223] = { id = 27223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retribution", description = "Where Market Row meets Festival Lane, you will encounter The Unforgiven. If you slay the entirety of Crusaders' Square, you will coax out Timmy the Cruel. Both of these former champions committed heinous acts against innocents here in the name of gaining unholy power.\n\nYou must destroy both of them and rid Stratholme of their foul presence. Take caution, for they were powerful fighters in life, and their new dark powers will only have made them even more deadly.", sourceObjective = "Kill The Unforgiven and Timmy the Cruel.", completion = "You may have this as a suitable reward. I found it nestled in the armor of one of the scourge here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27225] = { id = 27225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Ander Germaine", description = "Ander Germaine has sent word that he wishes to honor you for your mastery of arms and your dedication to the Alliance. Make your way to Stormwind, leave the Old Town district through the south exit, and speak with him in his Command Center. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", sourceObjective = "Speak to Ander Germaine in Stormwind's Command Center.", completion = "It's good to see that you received my message. I have something important I wish to discuss with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27226] = { id = 27226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hair of the Dog", description = "Thank the Warchief that you're here, {name}. I've made a critical error with the sea dogs and need your help to rectify the situation.\n\nYou see, I sent them out against the worgen coming from Fenris Isle stone cold sober. They attacked the beasts and promptly got their butts handed to them. Many of them died, but a few still live, barely clinging on to dear life.\n\nTake this barrel of ale to the Decrepit Fields, east of here, and force it down the throats of fallen sea dogs.", sourceObjective = "Rouse 8 Orc Sea Dogs.", completion = "A-HA! I knew it! Lesson learned, I suppose. We will not fail again. I will be sure to have some ale on hand at the front lines.", sourceObjectiveStatus = "unverified-source-field" }
quests[27227] = { id = 27227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Aurius Rivendare", description = "This Chapel is the last Light amongst so much darkness. Ras Frostwhisper took his own life in the slaughterhouse, carving his face into a macabre smile in front of the Lich King, who raised him into the Lich that now haunts Scholomance.\n\nThe ground where that atrocity occured is now Scourge holy ground, blessed by the Lich King with the very darkest magic. Lord Aurius Rivendare, new ruler of Stratholme, now guards it and continues his master's evil work. Slay him without pause.", sourceObjective = "Kill Lord Aurius Rivendare.", completion = "Stratholme will become a paragon of all that is good in this world. You have my thanks for your part in this mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[27228] = { id = 27228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man Against Abomination", description = "Deep within, you will find Ramstein the Gorger. I cannot bear to tell you the atrocities this monster has commited. Know only this - he deserves to feel the full wrath of countless lost souls, a wrath you will bring upon him.\n\nHave no mercy. Be unwavering in your fury.", sourceObjective = "Slaughter Ramstein the Gorger.", completion = "I respect the power you demonstrated in killing Ramstein. With proper rage backing your actions, I think even the Scourge can know fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[27229] = { id = 27229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SMASH BROODQUEEN", description = "<The following is written in very large print.>\n\nSPIDERS IN NORTH CAVE BAD. POISON OGRES. OGRES GET SICK. BAD!\n\nBIG BIG SPIDER IN CAVE MAKE MORE SPIDERS. MORE SPIDERS BAD!\n\nKILL BIG SPIDER, STOP MORE SPIDERS. KILL BIG SPIDER, GET BIG PRIZE! GOOD!\n\n<A crude drawing accompanies this.>", sourceObjective = "Obtain the Broodqueen Pedipalp.", progress = "Are you here about the sign?\n\nI don't want to talk about it unless you've got proof of a kill.", completion = "By Grom, I'm glad that's over with. If you read that sign you may have some idea how desperate I got after trying to communicate to these lumbering oafs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27230] = { id = 27230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons for War", description = "The Scourge are adept at forging powerful armaments for their soldiers, making it difficult for our men to kill 'em! There are blacksmithing plans near the Baroness Anastari's ziggurat that their chief swordsmith plans to use for an extremely powerful weapon for Lord Aurius.\n\nWe're going to prevent that weapon from being made and stop their regular arms flow with one blow! Go take the plans and kill the Black Guard Swordsmith when he comes to defend 'em, and it'll make our mission much easier.", sourceObjective = "Kill the Black Guard Swordsmith.", progress = "You need to kill their swordsmith! Go!", completion = "Great! Without a steady flow of their weapons, we'll win through attrition!", sourceObjectiveStatus = "unverified-source-field" }
quests[27231] = { id = 27231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements from Fenris", description = "Those that survived your assault on Fenris managed to drink the blood of the wolf. They turned into ferocious worgen, hell-bent on vengeance. Now they paddle across Lordamere Lake and assault my sea dogs. Many have already been killed. The worgen monsters must be stopped!\n\nMake your way to the Decrepit Fields, east of here, and kill the Hillsbrad worgen that infest the area. Once you've killed them all, make your way to the Horde communication panel, located at the docks. I'll be in touch.", sourceObjective = "Kill 10 Hillsbrad Worgen.", progress = "Report?", completion = "<Hatchet's communication device crackles.>\n\nHatchet here, are they all dead?", sourceObjectiveStatus = "unverified-source-field" }
quests[27232] = { id = 27232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waters Run Red...", description = "<The communication console hums.>\n\nThose worgen you killed were the scouting party. There are hundreds more incoming! Looks like Crowley and Bloodfang made the blood offering to every human in Lordaeron.\n\nGet in one of those Horde cannons and send them all back to their makers. Let the waters of Lordamere Lake run red with their blood!", sourceObjective = "Kill 50 Hillsbrad Worgen with the Horde Cannon.", completion = "Though you killed a large number of the newly turned worgen, many more are sure to appear. Still, their assault will have softened. Well done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27233] = { id = 27233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "I can handle training from here.  If you're looking for something else to do, I recommend heading up the road to the northwest.  The Cenarion druids and Argent Crusade have a small camp set up there, at Dalson's old farm.  Maybe they can keep you busy until we need your help again.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27234] = { id = 27234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas... the symbol of the Defias!\n\nThe reports indicate their leader resides on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", sourceObjective = "Obtain the Defias Orders from Garn Mathers.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.", sourceObjectiveStatus = "unverified-source-field" }
quests[27235] = { id = 27235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", sourceObjective = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", progress = "Well met, {class}. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo.", sourceObjectiveStatus = "unverified-source-field" }
quests[27236] = { id = 27236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secondhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", sourceObjective = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27237] = { id = 27237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", sourceObjective = "Collect 1 Salvaged Strongbox.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here....", sourceObjectiveStatus = "unverified-source-field" }
quests[27238] = { id = 27238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, {name}. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", sourceObjective = "Speak with Lady Jaina Proudmoore in Theramore.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. Now, we must confirm your findings. The implications are too great if we are wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[27239] = { id = 27239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the mystery of the Defias' involvement in this kidnapping.", sourceObjective = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island.", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias have allied themselves with HER? The traitor?\n\n<Lady Jaina composes herself and prepares to explain.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27240] = { id = 27240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", sourceObjective = "Speak with Jaina to travel to Stormwind and meet with King Varian Wrynn.", completion = "So it was the Defias who served as the hands of Onyxia in this plot?\n\n<The king's face grows red with anger and his hands clench into fists.>\n\nYou and Lady Jaina have done Stormwind a great service this day. The traitors will not live long enough to regret their crimes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27241] = { id = 27241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Jaina", description = "I must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", sourceObjective = "Return to Lady Jaina Proudmoore in Theramore.", completion = "I have no doubt that the king meant every word when he told you he plans to destroy the Defias once and for all. He does not make promises lightly, and the enemies of Stormwind should know it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27242] = { id = 27242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture Bloodfen raptors or Bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", sourceObjective = "Use the Sturdy Rope to capture 6 Bloodfen Raptors or Bloodfen Screechers.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them.", sourceObjectiveStatus = "unverified-source-field" }
quests[27243] = { id = 27243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", sourceObjective = "Place the Raptor Bait near the windmill in Blackhoof Village.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[27244] = { id = 27244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", sourceObjective = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, {name}.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...", sourceObjectiveStatus = "unverified-source-field" }
quests[27245] = { id = 27245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, {class}, just bring back my men alive.", sourceObjective = "Collect Grimtotem Keys from the Grimtotem Tauren in Blackhoof Village and use them to free 5 Theramore Prisoners.", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men.", sourceObjectiveStatus = "unverified-source-field" }
quests[27246] = { id = 27246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", sourceObjective = "Bring the Spy's Report to Lieutenant Aden in Theramore.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!", sourceObjectiveStatus = "unverified-source-field" }
quests[27247] = { id = 27247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Vimes", description = "Captain Vimes should see the orc report you found, {name}.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", sourceObjective = "Bring the Spy's Report to Captain Garran Vimes.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says...", sourceObjectiveStatus = "unverified-source-field" }
quests[27248] = { id = 27248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[27249] = { id = 27249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the monsters who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", sourceObjective = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates.", sourceObjectiveStatus = "unverified-source-field" }
quests[27250] = { id = 27250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BAD COPY", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?", sourceObjective = "Speak with Vincent Hyal in Menethil Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27251] = { id = 27251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", sourceObjective = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble.", sourceObjectiveStatus = "unverified-source-field" }
quests[27252] = { id = 27252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", sourceObjective = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27253] = { id = 27253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. I had a man placed in that inn as a spy and I don't trust in the competence of these humans to uncover what happened.\n\nWhatever you find, don't give a scrap of it to that investigator. We'll handle this ourselves.", sourceObjective = "Investigate the Shady Rest Inn in at the border of the Barrens in Dustwallow Marsh.", completion = "<The inspector regards you with what can only be disdain and distrust.>\n\nLeave this place be, errand boy, or I'll be sure to bring a contingent of guard with me next time to sink the lesson home.", sourceObjectiveStatus = "unverified-source-field" }
quests[27254] = { id = 27254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", sourceObjective = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", progress = "What's that you have there, {name}? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?", sourceObjectiveStatus = "unverified-source-field" }
quests[27255] = { id = 27255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", sourceObjective = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", progress = "Something for me, {class}?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, {name}.\n\nYou should know that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27256] = { id = 27256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", sourceObjective = "Collect 5 Acidic Venom Sacs from Darkmist spiders.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, {name}. Now I rip them open and pour them onto the shield...", sourceObjectiveStatus = "unverified-source-field" }
quests[27257] = { id = 27257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", sourceObjective = "Speak with Krog in Brackenwall Village.", completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything...", sourceObjectiveStatus = "unverified-source-field" }
quests[27258] = { id = 27258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", sourceObjective = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", progress = "Hello there, {class}. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, {name}. I craft so many different shields and sets of armor, I can't keep track of them all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27259] = { id = 27259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", sourceObjective = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27260] = { id = 27260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", sourceObjective = "Bring Reethe's Badge to Krog in Brackenwall Village.", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "Hmm... now this is interesting.", sourceObjectiveStatus = "unverified-source-field" }
quests[27261] = { id = 27261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", sourceObjective = "Go with Ogron to speak with Reethe.", completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[27262] = { id = 27262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", sourceObjective = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27263] = { id = 27263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", sourceObjective = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27264] = { id = 27264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", sourceObjective = "Find out more about Reethe from Adjutant Tesoran in Theramore.", completion = "Hello, {name}. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book.", sourceObjectiveStatus = "unverified-source-field" }
quests[27265] = { id = 27265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Shadowbreaker", description = "Lord Grayson Shadowbreaker, one of the foremost paladins in the realm, has asked to speak with you personally. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.\n\nYou should make your way to Stormwind immediately and meet him inside the city's Cathedral of Light.", sourceObjective = "Speak to Lord Grayson Shadowbreaker in Stormwind's Cathedral of Light.", completion = "It heartens me to see that my message found you, {name}. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27266] = { id = 27266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulf Calls", description = "Wulf Hansreim oversees the training and coordination of hunters in the service of Stormwind. He has asked to speak to you personally. As soon as you are able, travel to Stormwind and exit the Old Town district through the south gate to reach his headquarters.\n\nI have no idea what he has planned, but it sounds like he has been impressed with your rapid progress.", sourceObjective = "Speak to Wulf Hansreim in Stormwind.", completion = "Ah, you've arrived. Make yourself at home, {name}. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27267] = { id = 27267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Contact with SI:7", description = "It seems that the leaders of SI:7 have taken an interest in your progress and your service to the Alliance. Osborne the Night Man, a high ranking member of SI:7, has asked to speak with you. Look for him in the southern part of Stormwind's Old Town.\n\nI'm not sure what Osborne wants with you, but it seemed important.", sourceObjective = "Speak to Osborne the Night Man in Stormwind's Old Town.", completion = "I hope my message didn't unnerve you, {name}. I have called you here to recognize your accomplishments.", sourceObjectiveStatus = "unverified-source-field" }
quests[27268] = { id = 27268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Haste to the Cathedral", description = "I have an urgent message for you from Stormwind, {name}. It seems that High Priestess Laurena has asked to speak with you at the Cathedral of Light in Stormwind's Cathedral Square. The messenger did not say what the matter concerned, but that you should travel to Stormwind with all haste.", sourceObjective = "Speak to High Priestess Laurena in Stormwind's Cathedral of the Light.", completion = "It heartens me to see that you received my message and responded so quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[27269] = { id = 27269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of the Moon", description = "I have an urgent message for you from Darnassus. The message is from the High Priestess of Elune, Tyrande Whisperwind, herself! The messenger did not say what the matter concerned, but that you should travel to the Temple of the Moon in Darnassus and meet with the high priestess at once.", sourceObjective = "Speak to Tyrande Whisperwind at the Temple of the Moon in Darnassus.", completion = "Welcome to the Temple of the Moon, {name}. I am glad that you chose to answer my summons so quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[27270] = { id = 27270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the Farseer", description = "I have an urgent message for you from Stormwind, {name}. It seems Farseer Umbrua has asked to speak with you the next time you're in the city.\n\nThe messenger gave no explanation for the farseer's invitation, but you should travel to Stormwind and find Farseer Umbrua at the Golden Keg in the Dwarven District as soon as you can.", sourceObjective = "Speak with Farseer Umbrua in at the Golden Keg Stormwind's Dwarven District.", completion = "Welcome, {name}. I am glad that you decided to accept my invitation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27271] = { id = 27271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Wizard's Sanctum", description = "I just received a message from Stormwind, {name}. One of Stormwind's most renowned mages, Maginor Dumas, has requested that you visit him in the Mage Quarter inside Stormwind. You will be able to find him inside the Wizard's Sanctum atop the large tower in the heart of the Mage Quarter.\n\nI do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", sourceObjective = "Speak with Maginor Dumas at the Wizard's Sanctum inside Stormwind's Mage Quarter.", completion = "Welcome to the Wizard's Sanctum, {name}. I have been watching your progress with interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27272] = { id = 27272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demisette Sends Word", description = "It seems that the elders in our ranks have taken notice of your progress and dedication, {name}. Demisette Cloyce, one of the oldest and most respected members of our circle, has sent word that she wishes to speak with you. You should not take such an invitation lightly. Most only speak with her in the course of their lessons, but if she has asked to see you personally, it must be an important matter.\n\nHurry back to Stormwind and look for her beneath the Slaughtered Lamb in the Mage Quarter.", sourceObjective = "Speak with Demisette Cloyce at the Slaughtered Lamb in Stormwind's Mage Quarter.", completion = "I see that my message managed to reach you. Good. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27273] = { id = 27273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation from Moonglade", description = "You just missed the messenger from Moonglade, {name}. He said little, except that he carried an urgent message from Loganaar, one of the honored trainers of the Cenarion Circle. Head to Moonglade as quickly as you can, {name}. The matter sounds important.\n\nLook for Loganaar in the village of Nighthaven.", sourceObjective = "Speak to Loganaar at Nighthaven in Moonglade.", completion = "I'm glad to see that you have arrived safely in Nighthaven, {name}. I offer you the welcome and the hospitality of the Cenarion Circle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27274] = { id = 27274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chief Surgeon", description = "I have an urgent message for you from Stormwind, {name}. Chief Surgeon Gashweld has asked to meet with you in Stormwind. The message didn't say what the chief surgeon wanted to discuss, but you should make your way to Stormwind as quickly as you can. Look for Chief Surgeon Gashweld in the Dwarven District of the city.", sourceObjective = "Speak to Chief Surgeon Gashweld in Stormwind's Dwarven District.", completion = "I see that you received my message. Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[27275] = { id = 27275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together Again", description = "We saw to it that the sentinel was healed and re-equipped. I already sent her back into the field.\n\nHead back up and go to Darkcloud Pinnacle. She'll meet you there.", sourceObjective = "Speak with the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", completion = "Good to see you again, {name}. Let us put the fear of the Goddess into the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[27276] = { id = 27276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together Again", description = "We saw to it that the brave was healed and re-equipped. I already sent him back into the field.\n\nHead back up and go to Darkcloud Pinnacle. He'll meet you there.", sourceObjective = "Speak with the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", completion = "I am honored by your presence, {name}. Let us put the fear of the Earth Mother into the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[27277] = { id = 27277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with Ureda", description = "I've received an urgent message from Orgrimmar for you, {name}. The renowned mage, Ureda, wants you to meet with her in Orgrimmar. I'm not sure what this is about, but if I was you, I would travel to the capital as fast as possible and seek out Ureda in the Cleft of Shadow.", sourceObjective = "Speak with Ureda in the Cleft of Shadow.", completion = "Ah, good. It seems my message did find you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27278] = { id = 27278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimshot's Call", description = "A courier from Orgrimmar just delivered a message for you. I'm to tell you that Ormak Grimshot, master of the hunters in Orgrimmar, has asked to meet with you.\n\nTravel quickly to Orgrimmar and present yourself to Ormak in the Valley of Honor.", sourceObjective = "Speak with Ormak Grimshot in the Valley of Honor.", completion = "Good, you're here. Let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[27279] = { id = 27279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Hand", description = "A messenger just arrived from Orgrimmar bearing a communication for you. Gordul, the senior rogue trainer in Orgrimmar, has sent for you. You must head to Orgrimmar immediately and meet with him in the Cleft of Shadow.\n\nWhen Gordul summons you, the prudent thing to do is obey. Do not keep him waiting, {name}.", sourceObjective = "Speak with Gordul in Orgrimmar's Cleft of Shadow.", completion = "Now that you are here, we can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27280] = { id = 27280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamseeker Calls", description = "Kardris Dreamseeker, a shaman whose wisdom is legendary in the Horde, has sent word that she wishes to speak with you. The messenger didn't mention what was so urgent, but you should make your way to Orgrimmar as quickly as you can and find Kardris in the Valley of Wisdom. She will be among others who offer training to young shamans.", sourceObjective = "Speak with Kardris Dreamseeker in the Valley of Wisdom.", completion = "I see you are both obedient and talented, {name}. Stay that way, and you will go far in the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27281] = { id = 27281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezz Ragefist", description = "I just received word that you are needed in Orgrimmar, {name}. Grezz Ragefist, the honored trainer of warriors in the city, has sent for you. It would not be wise to ignore such a summons.\n\nTravel quickly to Orgrimmar and the Valley of Honor where Grezz awaits your arrival.", sourceObjective = "Speak with Grezz Ragefist in the Valley of Honor.", completion = "I see you are both obedient and talented, {name}. Stay that way, and you will go far in the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27282] = { id = 27282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zevrost's Behest", description = "{name}, I have received word that you are needed back in Orgrimmar. Zevrost, one of the senior warlock trainers in the Cleft of Shadow, has something important that he wishes to discuss with you. It seems like the kind of thing that cannot wait.\n\nMake your way back to Orgrimmar and speak with him as soon as you can.", sourceObjective = "Speak with Zevrost in the Cleft of Shadow.", completion = "Ah, you're here at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[27283] = { id = 27283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Journey to Moonglade", description = "As you have heard, Moonglade is the home of the Cenarion Circle, the brotherhood of druids. All who dwell there do so in the peace of Cenarius. It is in that spirit that the trainer Loganaar has extended an invitation to visit him in Moonglade.\n\nYou will find him in the village of Nighthaven.", sourceObjective = "Speak with Loganaar in Nighthaven.", completion = "Welcome to Moonglade, {name}. I have been looking forward to meeting you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27284] = { id = 27284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "I'm sorry I can't be of much help, {name}, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", sourceObjective = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27285] = { id = 27285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", sourceObjective = "Speak with Captain Garran Vimes in Theramore.", completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.", sourceObjectiveStatus = "unverified-source-field" }
quests[27286] = { id = 27286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", sourceObjective = "Return the information about Reethe to Captain Garran Vimes in Theramore.", completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27287] = { id = 27287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, {name}. He may be a tough nut to crack.", sourceObjective = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", completion = "Did Vimes send you? Couldn't do his dirty work himself, could he...", sourceObjectiveStatus = "unverified-source-field" }
quests[27288] = { id = 27288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", sourceObjective = "Speak with Captain Garran Vimes in Theramore about Reethe.", completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.", sourceObjectiveStatus = "unverified-source-field" }
quests[27289] = { id = 27289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vimes's Report", description = "You've done some good work, {name}, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.", sourceObjective = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[27290] = { id = 27290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Forsaken Forward Command", description = "The time has come to destroy Crowley, Bloodfang and every dog at their command. To do this, though, will require cunning and planning the likes of which they would never dare dream!\n\nAs one of my most trusted soldiers, {name}, I need you to go to Forsaken Forward Command, located in Gilneas, and report to Deathstalker Commander Belmont. I have sent Belmont ahead with my plans. He awaits your arrival.\n\nArthura will escort you to Forward Command. Tell me when you are ready and I will send you on your way.", sourceObjective = "Report to Deathstalker Commander Belmont at Forsaken Forward Command in Gilneas.", completion = "Well if it isn't Barksdalenub!\n\nI hope you're ready for battle, because that's all you'll find in this hellhole. We're at the heart of contested territory and these worgen mongrels won't give an inch!", sourceObjectiveStatus = "unverified-source-field" }
quests[27291] = { id = 27291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the stones in the graveyard just north of Theramore's gates.", sourceObjective = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27292] = { id = 27292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", sourceObjective = "Speak with Krog at Brackenwall Village.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.", sourceObjectiveStatus = "unverified-source-field" }
quests[27293] = { id = 27293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", sourceObjective = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. We knew nothing of these plans and we lost a good man because of it. I don't trust that we're not next on their list.", sourceObjectiveStatus = "unverified-source-field" }
quests[27294] = { id = 27294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm lead to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", sourceObjective = "Collect 7 Blackhoof Armaments from Blackhoof Village.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[27295] = { id = 27295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", sourceObjective = "Speak with Tabetha at her farm in the Quagmire.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[27296] = { id = 27296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. If I know him, he'll appreciate the taste of vengeance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27297] = { id = 27297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh, though I get the impression you probably don't mind that. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nGo tell your leader that his vengeance has been sated.", sourceObjective = "Return to Krog at Brackenwall Village.", completion = "<Krog listens to your report.>\n\nI'm impressed, {name}. I would've thought that the Grimtotem criminals would've been more difficult to locate. The Alliance are truly incompetent.\n\nIn truth, I just sought to answer the death of one of my men, but this situation has been more fortunate than expected. If the Grimtotem choose to retaliate, it will likely be against the Alliance. Perhaps we will soon have the manpower to drive the scum from these shores once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27298] = { id = 27298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Master Pyreanor", description = "Master Pyreanor, a senior Blood Knight and advisor to the warchief, requires your presence in Orgrimmar. He has taken an interest in your training, {name}, and it is imperative that you speak with him immediately.\n\nThe message I received didn't mention the reason he requested your visit, but you should set out for Orgrimmar right away. Master Pyreanor can be found in the keep in the center of the Valley of Strength.", sourceObjective = "Speak with Master Pyreanor in Orgrimmar's Valley of Strength.", completion = "I've heard much about you, {name}. You have a bright future ahead of you in the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27299] = { id = 27299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torn Ground", description = "It won't be takin' much convincin' to turn us against da Twilight - dat's already our goal. We've already come to battle here though, so we may be needin' ya help before we can turn towards dey're fortress.\n\nDa Twilight have already brought Iso'rath up from da ground to the south, I'm sure ya noticed. It's tentacles have been burstin' from da ground all around us. We could use a hand beatin' them down if you be willin'.", sourceObjective = "Kill 3 Tentacles of Iso'rath.", progress = "Did ya have any luck with dose tentacles?", completion = "Tank ya, {class}. A bit of breathin' room helps a lot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27300] = { id = 27300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Back", description = "Da Twilight's Hammer have destroyed a Dragonmaw town to the south and are performin' dey're summonin' rituals from there. Offer dem no respite to continue wit dey're incantations. Bring tha battle to dem!", sourceObjective = "Kill 12 Twilight's Hammer at the Ruins of Drakgor.", completion = "Revenge is bittersweet, but I'm glad we be havin' someone as powerful as you do see dis done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27301] = { id = 27301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbroken", description = "We are preparing a ritual that may be of use in destroying Iso'rath, the old god bred abomination that the Twilight's Hammer have brought up from the depths. We are delayed though, for one of our strongest was captured during an assault on their encampment.\n\nEarthcaller Yevaa is within the ruins to the south. She is not dead. I am sure of it. Please, rescue her. If any of us is deserving of your aid, it is her.", sourceObjective = "Find Earthcaller Yevaa within the Ruins of Drakgor.", completion = "Thank the elements that you've come. Did my brothers send you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27302] = { id = 27302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Solutions", description = "I'm new to this gig. Very new. But ya know what? That gives me perspective!\n\nThese shaman buddies of mine have come upon somethin' great, but they're too single minded! They lean on the elements and they forget to make use of the common materials all around them.\n\nIn the ruins to the south, I saw those Twilight goons tote in barrels of flammable oil! They used it when they razed the town. I say we use it when we raze them.", sourceObjective = "Gather 10 barrels of Pyreburn Oil.", progress = "I wonder what happens when you douse an elemental with that stuff. Jumbo-super-bonfire-elemental? I'm thinkin' so. We'll have to try.", completion = "Now that's what I'm talkin' about! Can you think of all the uses for this stuff? I definitely can't. But I can think of a lot, and I'm liking the possibilities.", sourceObjectiveStatus = "unverified-source-field" }
